insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ يَعْلَى بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِعُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: {لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا} [النساء: ١٠١] فَقَدْ أَمِنَ النَّاسُ؟ فَقَالَ: عَجِبْتُ مِمَّا عَجِبْتَ مِنْهُ، فَسَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَقَالَ: "صَدَقَةٌ تَصَدَّقَ اللهُ بِهَا عَلَيْكُمْ، فَاقْبَلُوا صَدَقَتَهُ". (م,د,ت,ن,جه)', 'യഅ്ലബിൻ ഉമയ്യ(റ): ഞാൻ ഉമറുബ്നുൽ ഖത്താബി(റ)നോട് ചോദിച്ചു: ''സത്യനിഷേധികൾ നിങ്ങളെ പീഢിപ്പിക്കുമെന്ന് (കുഴപ്പത്തിലാക്കുമെന്ന്) ഭയപ്പെടുന്നുവെങ്കിൽ നിങ്ങൾ നിസ്കാരം ഖസ്ർ ആക്കുന്നതിൽ (ചുരുക്കിനിർവ്വഹിക്കുന്നതിൽ) നിങ്ങൾക്ക് കുറ്റം ഇല്ല'' (അന്നിസാഅ് 101). ഇപ്പോൾ ജനങ്ങൾ നിസ്സംശയം നിർഭയരായിരിക്കുന്നുവല്ലോ? അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: നിങ്ങൾ അത്ഭുതം പ്രകടിപ്പിച്ച ഇക്കാര്യത്തിൽ ഞാനും അത്ഭുതപ്പെട്ടിരുന്നു. അങ്ങനെ ഇക്കാര്യത്തെപ്പറ്റി റസൂലി(സ)നോട് ഞാൻ ചോദിച്ചു. അവിടുന്ന് പറഞ്ഞു: "അത് അല്ലാഹു നിങ്ങൾക്ക് നൽകിയ ഒരു ദാനമാണ്. അവന്റെ ദാനത്തെ നിങ്ങൾ സ്വീകരിച്ചു കൊള്ളുക." (മു,ദ,തു,ന,ജ)', 'يَعْلَى بْنِ أُمَيَّةَ', 'യഅ്ലബിൻ ഉമയ്യ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], 'النساء: ١٠١', null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أُمَيَّةَ بْنِ عَبْدِ اللهِ ابْنِ خَالد: أَنَّهُ قَالَ لِعَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: إِنَّا نَجِدُ صَلَاةَ الْحَضَرِ وَصَلَاةَ الْخَوْفِ فِي الْقُرْآنِ، وَلَا نَجِدُ صَلَاةَ السَّفَرِ فِي الْقُرْآنِ؟ فَقَالَ لَهُ ابْنُ عُمَرَ: يَا ابْنَ أَخِي، إِنَّ اللهَ عَزَّ وَجَلَّ بَعَثَ إِلَيْنَا مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا نَعْلَمُ شَيْئًا، وَإِنَّمَا نَفْعَلُ كَمَا رَأَيْنَا مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ. (ن)', 'ഉമയ്യത്തുബിൻ അബ്ദുല്ലാഹിബിൻ ഖാലിദ്(റ): അദ്ദേഹം അബ്ദുല്ലാഹിബിൻ ഉമറി(റ)നോട് ചേദിച്ചു: നിശ്ചയം സ്വദേശത്തുള്ള നിസ്കാരത്തെ സംബന്ധിച്ചും യുദ്ധസമയത്തുള്ള നിസ്കാരത്തെ സംബന്ധിച്ചും ഖുർആനിൽ നാം കാണുന്നുണ്ട്. എന്നാൽ, യാത്രാവേളയിലുള്ള നിസ്കാരത്തെ സംബന്ധിച്ച് ഖുർആനിൽ നാം കാണുന്നില്ലല്ലോ? അപ്പോൾ ഇബ്നുഉമർ(റ) (നിവേദകനോട്) പറഞ്ഞു: എന്റെ സഹോദരപുത്രാ! നിശ്ചയം അല്ലാഹു നബി(സ)യെ നമ്മിലേക്ക് നിയോഗിച്ചത് നാം ഒന്നും അറിയാത്ത അവസ്ഥയിലായിരുന്നു. നിശ്ചയം മുഹമ്മദ് നബി(സ) എപ്രകാരം പ്രവർത്തിക്കുന്നതായി നാം കണ്ടുവോ അപ്രകാരമാണ് നാം പ്രവർത്തിക്കുന്നത്. (ന)', 'أُمَيَّةَ بْنِ عَبْدِ اللهِ ابْنِ خَالد', 'ഉമയ്യത്തുബിൻ അബ്ദുല്ലാഹിബിൻ ഖാലിദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ فِي السَّفَرِ رَكْعَتَيْنِ، وَبَعْدَهَا رَكْعَتَيْنِ. حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): റസൂലി(സ)നോടൊപ്പം യാത്രാവേളയിൽ ദുഹ്ർ രണ്ട് റക്അത്തായി ഞാൻ നിസ്കരിച്ചു. ളുഹ്റിന് ശേഷം രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ وَالسَّفَرِ، فَصَلَّيْتُ مَعَهُ فِي الْحَضَرِ الظُّهْرَ أَرْبَعًا وَبَعْدَهَا رَكْعَتَيْنِ، وَصَلَّيْتُ مَعَهُ فِي السَّفَرِ الظُّهْرَ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ، وَالْعَصْرَ رَكْعَتَيْنِ وَلَمْ يُصَلِّ بَعْدَهَا شَيْئًا، وَالْمَغْرِبَ فِي الْحَضَرِ وَالسَّفَرِ سَوَاءً: ثَلَاثَ رَكَعَاتٍ، لَا تَنْقُصُ فِي الْحَضَرِ وَلَا فِي السَّفَرِ، هِيَ وِتْرُ النَّهَارِ، وَبَعْدَهَا رَكْعَتَيْنِ. حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): സ്വദേശത്തും യാത്രയിലും നബി(സ)യോടൊപ്പം ഞാൻ നിസ്കരിച്ചു. സ്വദേശത്ത് ളുഹ്റിനെ നാല് റക്അത്തായി തിരുമേനി(സ)യോടൊപ്പം ഞാൻ നിസ്കരിച്ചു. ളുഹ്റിന് ശേഷം രണ്ട് റക്അത്തും, യാത്രയിൽ ളുഹ്റിനെ രണ്ട് റക്അത്തായി അവിടത്തോടൊപ്പം ഞാൻ നിസ്കരിച്ചു. അതിന് ശേഷം രണ്ട് റക്അത്ത്. അസ്റിനെ രണ്ട് റക്അത്തായും (തിരുമേനിയോടൊപ്പം ഞാൻ നിസ്കരിച്ചു). എന്നാൽ അസ്റിന്റെ (ഫർള്) ശേഷം അവുടുന്ന് ഒന്നും നിസ്കരിച്ചില്ല. മഗ്രിബ് സ്വദേശത്തും യാത്രയിലും സമമായി (നബി(സ)യോടൊപ്പം ഞാൻ നിസ്കരിച്ചു) മൂന്ന് റക്അത്തുകൾ, അത് സ്വദേശത്തും യാത്രയിലും കുറയുകയില്ല; അത് പകലിന്റെ വിത്റാണ്. മഗ്രിബിന്റെ ഫർളിന് ശേഷവും രണ്ട് റക്അത്ത്. ഹദീസ് ഹസനാണ്. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 699, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ لِامْرَأَةٍ، تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ، أَنْ تُسَافِرَ مَسِيرَةَ يَوْمٍ وَلَيْلَةٍ لَيْسَ مَعَهَا حُرْمَةٌ". (خ)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്ന ഒരു സ്ത്രീക്ക് തന്നെ വിവാഹം ചെയ്യൽ നിഷിദ്ധമായ (അടുത്തബന്ധമുള്ള) ഒരു പുരുഷൻ അവളുടെ കൂടെയില്ലാതെ ഒരു രാപ്പകൽ സമയത്തെ ദൂരം യാത്ര ചെയ്യൽ അനുവദനീയമാകുന്നില്ല." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَعْجَلَهُ السَّيْرُ يُؤَخِّرُ الْمَغْرِبَ فَيُصَلِّيهَا ثَلَاثًا، ثُمَّ يُسَلِّمُ ثُمَّ قَلَّمَا يَلْبَثُ حَتَّى يُقِيمَ الْعِشَاءَ، فَيُصَلِّيهَا رَكْعَتَيْنِ، ثُمَّ يُسَلِّمُ، وَلَا يُسَبِّحُ بَعْدَ الْعِشَاءِ، حَتَّى يَقُومَ مِنْ جَوْفِ اللَّيْلِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): യാത്രയിലെ സഞ്ചാരം പ്രവാചകനെ(സ) ധൃതിപ്പെടുത്തിയാൽ മഗ്രിബിനെ അവിടുന്ന് പിന്തിപ്പിച്ച് അതിനെ മൂന്നായി നിസ്കരിക്കുകയും പിന്നീട് അവിടുന്ന് സലാം വീട്ടുകയും, പിന്നെ കുറഞ്ഞ സമയം താമസിച്ച ശേഷം ഇശാഇനു വേണ്ടി എഴുന്നേൽക്കുകയും, രണ്ട് റക്അത്ത് നിസ്കരിച്ച് സലാം വീട്ടുകയും ചെയ്യുന്നതായി അല്ലാഹുവിന്റെ റസൂലി(സ)നെ ഞാൻ കണ്ടു. ഇശാഇന് ശേഷം അവിടുന്ന് സുന്നത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നില്ല. യാത്രയുടെ അന്ത്യ യാമങ്ങളിൽ (നിസ്കാരത്തിനായി) അവിടുന്ന് എഴുന്നേൽക്കുന്നതു വരെ. (ബു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نَسِيرُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ مَكَّةَ وَالْمَدِينَةِ. لَا نَخَافُ إِلَّا اللهَ عَزَّ وَجَلَّ، نُصَلِّي رَكْعَتَيْنِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂലി(സ)നോടൊപ്പം മക്കക്കും മദീനക്കും മദ്ധ്യേ ഞങ്ങൾ യാത്രചെയ്യുമായിരുന്നു. അല്ലാഹുവിനെയല്ലാതെ മറ്റാരെയും ഭയപ്പെടാത്ത സന്ദർഭത്തിലും ഞങ്ങൾ രണ്ട് റക്അത്തായിട്ടാണ് നിസ്കരിച്ചിരുന്നത്. (ന)', 'ابْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ السِّمْطِ قَالَ: رَأَيْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ يُصَلِّي بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ، فَسَأَلْتُهُ عَنْ ذَلِكَ، فَقَالَ: إِنَّمَا أَفْعَلُ كَمَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ. (ن)', 'ഇബ്നുസ്സിംത്വ്(റ): ദുൽഖുലൈഫയിൽ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കുന്നതായി ഉമറുബ്നുൽ ഖത്താബി(റ)നെ ഞാൻ കണ്ടു. അതിനെപ്പറ്റി ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) എപ്രകാരം പ്രവർത്തിക്കുന്നതായി ഞാൻ കണ്ടുവോ അപ്രകാരമാണ് ഞാൻ പ്രവർത്തിക്കുന്നത്. (ന)', 'ابْنِ السِّمْطِ قَالَ', 'ഇബ്നുസ്സിംത്വ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ رَكْعَتَيْنِ، وَمَعَ أَبِي بَكْرٍ رَكْعَتَيْنِ، وَمَعَ عُمَرَ رَكْعَتَيْنِ، رَضِيَ اللهُ عَنْهُمَا. (ن)', 'അബ്ദുല്ല(റ): റസൂലി(സ)നോടൊപ്പം യാത്രാ വേളയിൽ രണ്ട് റക്അത്തായി ഞാൻ നിസ്കരിച്ചു. അബൂബക്റി(റ)നോടൊപ്പവും രണ്ട് റക്അത്തായി (ഞാൻ നിസ്കരിച്ചു). ഉമറി(റ)നോടൊപ്പവും രണ്ട് റക്അത്തായി (ഞാൻ നിസ്കരിച്ചു). (ന)', 'عَبْدِ اللهِ', 'അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَاةُ الْجُمُعَةِ رَكْعَتَانِ، وَالْفِطْرِ رَكْعَتَانِ، وَالنَّحْرِ رَكْعَتَانِ، وَالسَّفَرِ رَكْعَتَانِ، تَمَامٌ غَيْرُ قَصْرٍ، عَلَى لِسَانِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن,جه)', 'ഉമർ(റ): ജുമുഅഃ നിസ്കാരം രണ്ട് റക്അത്താണ്. ചെറിയ പെരുന്നാൾ (നിസ്കാരവും) രണ്ട് റക്അത്താണ്, വലിയ പെരുന്നാൾ (നിസ്കാരവും)രണ്ട് റക്അത്താണ്. യാത്രാവേളയിലുള്ള നിസ്കാരവും രണ്ട് റക്അത്താണ്. നബി(സ)യുടെ നാവിലൂടെ പഠിപ്പിച്ച ചുരുക്കാത്ത നിലയിലുള്ള പൂർണ്ണമായ നിസ്കാരം തന്നെയാണിത്. (ന,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ اللهَ عَزَّ وَجَلَّ فَرَضَ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ أَرْبَعًا، وَفِي السَّفَرِ رَكْعَتَيْنِ، وَفِي الْخَوْفِ رَكْعَةً. (م,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം അല്ലാഹു നിങ്ങളുടെ നബി(സ)യുടെ നാവിലൂടെ സ്വദേശത്ത് നാല് റക്അത്തായും, യാത്രയിൽ രണ്ട് റക്അത്തായും, ശത്രുഭയമുള്ളപ്പോൾ ഒരു റക്അത്തായും നിസ്കാരത്തെ നിർബന്ധ കടമയാക്കിയിരിക്കുന്നു. (മു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فُرِضَتِ الصَّلَاةُ رَكْعَتَيْنِ رَكْعَتَيْنِ فِي الْحَضَرِ وَالسَّفَرِ، فَأُقِرَّتْ صَلَاةُ السَّفَرِ، وَزِيدَ فِي صَلَاةِ الْحَضَرِ. (ق,د,ن)', 'ആഇശ(റ): സ്വദേശത്തും യാത്രയിലും നിസ്കാരം രണ്ട് റക്അത്തായിട്ടാണ് നിർബന്ധകടമയാക്കപ്പെട്ടത്. എന്നാൽ യാത്രയുടെ നിസ്കാരം സ്ഥിരപ്പെടുത്തപ്പെടുകയും സ്വദേശത്തെ നിസ്കാരം അധികരിപ്പിക്കപ്പെടുകയും ചെയ്തു. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مِنْ هَذِهِ الْمَدِينَةِ لَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى يَرْجِعَ إِلَيْهَا. (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഈ മദീനയിൽനിന്ന് പുറപ്പെട്ടാൽ തിരിച്ചുവരുന്നതുവരെ (മദീനയിലേക്ക് മടങ്ങിവരുന്നതുവരെ) രണ്ട് റക്അത്തിനേക്കാൾ കൂടുതലായി നിസ്കരിക്കുമായിരുന്നില്ല. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: افْتَرَضَ اللهُ الصَّلَاةَ عَلَى لِسَانِ نَبِيِّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ أَرْبَعًا، وَفِي السَّفَرِ رَكْعَتَيْنِ. (م,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നാട്ടിൽ താമസിക്കുന്നവന് നാല് റക്അത്തും യാത്രക്കാരന് രണ്ട് റക്അത്തും നിങ്ങളുടെ നബി(സ)യുടെ നാവിലൂടെ അല്ലാഹു നിർബന്ധമാക്കിയിരിക്കുന്നു. (മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَافَرْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ، فَكَانُوا يُصَلُّونَ الظُّهْرَ وَالْعَصْرَ رَكْعَتَيْنِ رَكْعَتَيْنِ، لَا يُصَلُّونَ قَبْلَهَا وَلَا بَعْدَهَا. وَقَالَ عَبْدُ اللهِ: لَوْ كُنْتُ مُصَلِّيًا قَبْلَهَا أَوْ بَعْدَهَا لَأَتْمَمْتُهَا. حَسَنٌ. (ت)', 'ഇബ്നുഉമർ(റ): നബി(സ)യോടൊപ്പവും, അബൂബക്ർ(റ), ഉമർ(റ), ഉസ്മാൻ(റ) എന്നിവരോടൊപ്പവും ഞാൻ യാത്ര ചെയ്തു. അവരെല്ലാവരും ളുഹ്റും അസ്റും ഈരണ്ട് റക്അത്തായി നിസ്കരിക്കുമായിരുന്നു. അവയ്ക്ക് മുമ്പും പിമ്പും അവർ നിസ്കരിക്കുന്നില്ല. അബ്ദുല്ല(റ) പറഞ്ഞു: അവയ്ക്കു മുമ്പോ പിമ്പോ ഞാൻ നിസ്കരിക്കുമായിരുന്നുവെങ്കിൽ ആ (ഫർള്) നിസ്കാരത്തെ ഞാൻ തീർച്ചയായും പൂർത്തിയാക്കി നിസ്കരിക്കുമായിരുന്നു. (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു) (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا، وَسُئِلَ عَنْ صَلَاةِ الْمُسَافِرِ؟ قَالَ: حَجَجْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى رَكْعَتَيْنِ، وَحَجَجْتُ مَعَ أَبِي بَكْرٍ فَصَلَّى رَكْعَتَيْنِ، وَمَعَ عُمَرَ فَصَلَّى رَكْعَتَيْنِ، وَمَعَ عُثْمَانَ سِتَّ سِنِينَ مِنْ خِلَافَتِهِ - أَوْ: ثَمَانِيَ سِنِينَ - فَصَلَّى رَكْعَتَيْنِ. حَسَنٌ صَحِيحٌ. (د,ت)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): യാത്രക്കാരന്റെ നിസ്ക്കാരത്തെപ്പറ്റി അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: റസൂലി(സ)നോടൊപ്പം ഞാൻ ഹജ്ജ് നിർവ്വഹിച്ചു. അപ്പോൾ നബി(സ) രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. അബൂബക്റി(റ)നോടൊപ്പവും ഞാൻ ഹജ്ജ് നിർവ്വഹിച്ചു. അദ്ദേഹവും രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. ഉമറി(റ)നോടൊപ്പവും ഞാൻ ഹജ്ജ് നിർവ്വഹിച്ചു. അദ്ദേഹവും രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. ഉസ്മാനി(റ)ന്റെ ഭരണകാലത്ത് ആറോ എട്ടോ വർഷം അദ്ദേഹത്തോടൊപ്പവും ഞാൻ ഹജ്ജ് നിർവ്വഹിച്ചു. അദ്ദേഹവും രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 701, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ لَا يَخَافُ إِلَّا اللهَ رَبَّ الْعَالَمِينَ، فَصَلَّى رَكْعَتَيْنِ. حَسَنٌ صَحِيحٌ. (ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം റസൂൽ(സ) മദീനയിൽ നിന്നും മക്കയിലേക്ക് പുറപ്പെട്ടു. ലോകരക്ഷിതാവായ അല്ലാഹുവിനെയല്ലാതെ ആരെയും അവിടുന്ന് ഭയപ്പെട്ടിരുന്നില്ല. (ആ അവസ്ഥയിൽ) അവിടുന്ന് രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ بِالْمَدِينَةِ أَرْبَعًا، وَصَلَّيْتُ مَعَهُ الْعَصْرَ بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ. (م,د,ت)', 'അനസുബ്നുമാലിക്(റ): റസൂലി(സ)നോടൊപ്പം മദീനായിൽ വച്ച് ഞാൻ ദുഹ്ർ നാല് റക്അത്തായി നിസ്കരിച്ചു. ദുൽഹുലൈഫയിൽവച്ച് നബി(സ)യോടൊപ്പം അസ്ർ രണ്ട് റക്അത്തായും ഞാൻ നിസ്കരിച്ചു. (മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ الزُّهْرِيِّ قَالَ: سَأَلْتُ السَّائِبَ ابْنَ يَزِيدَ، رَضِيَ اللهُ عَنْهُمَا: مَاذَا سَمِعْتَ فِي سُكْنَى مَكَّةَ؟ قَالَ: سَمِعْتُ الْعَلَاءَ بْنَ الْحَضْرَمِيِّ - رَضِيَ اللهُ عَنْهُ - يَقُولُ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثًا لِلْمُهَاجِرِ بَعْدَ الصَّدَرِ". (ق,ت,ن,جه)', 'അബ്ദുർറഹ്മാനുബ്നു ഹുമൈദുസ്സുഹ്രി(റ): സാഇബുബ്നു യസീദി(റ)നോട് ഞാൻ ചോദിച്ചു: മക്കയിലെ താമസകാലത്തെ നിസ്കാരത്തെപ്പറ്റി താങ്കൾ എന്താണ് കേട്ടിട്ടുള്ളത്? അദ്ദേഹം പറഞ്ഞു: അലാഅ് ബ്ൻ അൽഹള്റമീ(റ) പറയുന്നതായി ഞാൻ കേട്ടു. നബി(സ) പറഞ്ഞു: "യാത്രക്കാരന് ഹജ്ജിന്റെ കർമ്മങ്ങൾ പൂർത്തിയാക്കി മക്കയിലേക്ക് മടങ്ങിയ ശേഷം മൂന്ന് ദിവസം (ചുരുക്കി നിസ്കരിക്കാം)." (ബു,മു,തു,ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ الزُّهْرِيِّ قَالَ', 'അബ്ദുർറഹ്മാനുബ്നു ഹുമൈദുസ്സുഹ്രി(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ صُبْحَ رَابِعَةٍ مَضَتْ مِنْ شَهْرِ ذِي الْحِجَّةِ. (ق,ن,جه)', 'ജാബിർ ബിൻ അബ്ദുല്ല(റ): നബി(സ) ദുൽഹജ്ജ് മാസത്തിലെ നാലാം പ്രഭാതത്തിലാണ് മക്കയിൽ എത്തിയത്. (ബു,മു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിർ ബിൻ അബ്ദുല്ല(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تِسْعَةَ عَشَرَ يَوْمًا يُصَلِّي رَكْعَتَيْنِ رَكْعَتَيْنِ، فَنَحْنُ إِذَا أَقَمْنَا أَكْثَرَ مِنْ ذَلِكَ صَلَّيْنَا أَرْبَعًا. (خ,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഈരണ്ട് റക്അത്ത് വീതം നിസ്കരിക്കുന്നവരായി പത്തൊൻപതു ദിവസം റസൂൽ(സ) (മക്കയിൽ) താമസിച്ചു. ഞങ്ങൾ അതിൽ കൂടുതൽ താമസിച്ചാൽ നാലാക്കി നിസ്കരിക്കാറുണ്ട്. (ബു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، وَقَدْ سُئِلَ عَنْ قَصْرِ الصَّلَاةِ، فَقَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مَسِيرَةَ ثَلَاثَةِ أَمْيَالٍ - أَوْ: ثَلَاثَةِ فَرَاسِخَ - يُصَلِّي رَكْعَتَيْنِ. (م,د)', 'അനസുബ്നു മാലിക്(റ): നിസ്കാരം ചുരുക്കുന്നതിനെ സംബന്ധിച്ച് അദ്ദേഹം ചോദിക്കപ്പെട്ടു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: മൂന്ന് മൈലോ മൂന്ന് ഫർസഖോ¹ ദൂരം പ്രവാചകൻ(സ) യാത്ര പുറപ്പെട്ടാൽ രണ്ട് റക്അത്താക്കി നിസ്കരിക്കുമായിരുന്നു. (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', '¹. ഫർസഖ് = കാതം അഥവാ 3 1/4 മൈൽ', null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: غَزَوْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَشَهِدْتُ مَعَهُ الْفَتْحَ، فَأَقَامَ بِمَكَّةَ ثَمَانِيَ عَشْرَةَ لَيْلَةً لَا يُصَلِّي إِلَّا رَكْعَتَيْنِ، وَيَقُولُ: "يَا أَهْلَ الْبَلَدِ، صَلُّوا أَرْبَعًا، فَإِنَّا قَوْمٌ سَفْرٌ". (د,ت)', 'ഇംറാൻ ബിൻ ഹുസൈൻ(റ): റസൂലി(സ)നോടൊപ്പം ഞാൻ യുദ്ധം ചെയ്തു. മക്കാ വിജയത്തിന്റെ സമയത്ത് ഞാൻ അവിടുത്തോടൊപ്പം സന്നിഹിതനാവുകയും ചെയ്തു. പതിനെട്ട് രാത്രികൾ തിരുമേനി(സ) മക്കയിൽ താമസിച്ചിട്ടും രണ്ട് റക്അത്തായിട്ടല്ലാതെ നിസ്കരിച്ചിരുന്നില്ല. "നാട്ടുകാരേ, നിങ്ങൾ നാല് റക്അത്താക്കി നിസ്കരിക്കുക, നിശ്ചയം ഞാൻ യാത്രക്കാരനാണ്" എന്ന് അവിടുന്ന് പറയുകയും ചെയ്യുമായിരുന്നു. (ദ,തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാൻ ബിൻ ഹുസൈൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقَامَ سَبْعَ عَشْرَةَ بِمَكَّةَ يَقْصُرُ الصَّلَاةَ. وَفِي رِوَايَةٍ: يُصَلِّي رَكْعَتَيْنِ. قَالَ ابْنُ عَبَّاسٍ: وَمَنْ أَقَامَ سَبْعَ عَشْرَةَ قَصَرَ، وَمَنْ أَقَامَ أَكْثَرَ أَتَمَّ. وَفِي رِوَايَةٍ: قَالَ: أَقَامَ تِسْعَ عَشْرَةَ. وَفِي رِوَايَةٍ: قَالَ: أَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ عَامَ الْفَتْحِ خَمْسَ عَشْرَةَ يَقْصُرُ الصَّلَاةَ. (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ചുരുക്കി നിസ്കരിക്കുന്ന അവസ്ഥയിൽ റസൂൽ(സ) പതിനേഴു ദിവസം മക്കയിൽ താമസിച്ചു. മറ്റൊരു നിവേദനത്തിൽ: ''രണ്ട് റക്അത്തായി നിസ്കരിക്കുന്നവരായികൊണ്ട്.'' ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: പതിനേഴു ദിവസം താമസിക്കുന്നവൻ ചുരുക്കി നിസ്കരിക്കണം. അതിൽകൂടുതൽ താമസിക്കുന്നവൻ പൂർത്തിയാക്കി നിസ്കരിക്കണം. മറ്റൊരു നിവേദനപ്രകാരം: പത്തൊൻപതു ദിവസം അവിടുന്ന് താമസിച്ചു. മറ്റൊരു നിവേദനപ്രകാരം മക്കാവിജയത്തിന്റെ വർഷം ചുരുക്കി നിസ്കരിക്കുന്നവരായ നിലയിൽ പതിനഞ്ച് ദിവസം റസൂൽ(സ) മക്കയിൽ താമസിച്ചു. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=24), 1, 'وَفِي رِوَايَةٍ: يُصَلِّي رَكْعَتَيْنِ. قَالَ ابْنُ عَبَّاسٍ: وَمَنْ أَقَامَ سَبْعَ عَشْرَةَ قَصَرَ، وَمَنْ أَقَامَ أَكْثَرَ أَتَمَّ.', 'മറ്റൊരു നിവേദനത്തിൽ: ''രണ്ട് റക്അത്തായി നിസ്കരിക്കുന്നവരായികൊണ്ട്.'' ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: പതിനേഴു ദിവസം താമസിക്കുന്നവൻ ചുരുക്കി നിസ്കരിക്കണം. അതിൽകൂടുതൽ താമസിക്കുന്നവൻ പൂർത്തിയാക്കി നിസ്കരിക്കണം.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=24), 2, 'وَفِي رِوَايَةٍ: قَالَ: أَقَامَ تِسْعَ عَشْرَةَ.', 'മറ്റൊരു നിവേദനപ്രകാരം: പത്തൊൻപതു ദിവസം അവിടുന്ന് താമസിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=24), 3, 'وَفِي رِوَايَةٍ: قَالَ: أَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ عَامَ الْفَتْحِ خَمْسَ عَشْرَةَ يَقْصُرُ الصَّلَاةَ. (خ,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനപ്രകാരം മക്കാവിജയത്തിന്റെ വർഷം ചുരുക്കി നിസ്കരിക്കുന്നവരായ നിലയിൽ പതിനഞ്ച് ദിവസം റസൂൽ(സ) മക്കയിൽ താമസിച്ചു. (ബു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ، فَكَانَ يُصَلِّي رَكْعَتَيْنِ حَتَّى رَجَعْنَا إِلَى الْمَدِينَةِ. فَقِيلَ: هَلْ أَقَمْتُمْ بِهَا شَيْئًا؟ قَالَ: أَقَمْنَا بِهَا عَشْرًا. (ق,د,ت,ن,جه)', 'അനസ്(റ): റസൂലി(സ)നോടൊപ്പം മദീനായിൽ നിന്നും ഞങ്ങൾ മക്കയിലേക്ക് പുറപ്പെട്ടു. ഞങ്ങൾ മടങ്ങുന്നത് വരെ രണ്ട് റക്അത്തായി തിരുമേനി(സ) നിസ്കരിച്ചു. അപ്പോൾ ചോദിക്കപ്പെട്ടു. നിങ്ങൾ അവിടെ വല്ല ദിവസവും താമസിച്ചോ? അദ്ദേഹം പറഞ്ഞു: പത്ത് ദിവസം താമസിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: كَانَ إِذَا سَافَرَ سَارَ بَعْدَ مَا تَغْرُبُ الشَّمْسُ حَتَّى تَكَادَ أَنْ تُظْلِمَ، ثُمَّ يَنْزِلُ فَيُصَلِّي الْمَغْرِبَ، ثُمَّ يَدْعُوا بِعَشَائِهِ فَيَتَعَشَّى، ثُمَّ يُصَلِّي الْعِشَاءَ، ثُمَّ يَرْتَحِلُ، وَيَقُولُ: هَكَذَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ. وَفِي رِوَايَةٍ: أَنَّ أَنَسًا رَضِيَ اللهُ عَنْهُ كَانَ يَجْمَعُ بَيْنَهُمَا حِينَ يَغِيبُ الشَّفَقُ، وَيَقُولُ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ ذَلِكَ. (د)', 'അലി(റ): അദ്ദേഹം യാത്രപുറപ്പെടുകയാണെങ്കിൽ സൂര്യൻ അസ്തമിച്ച ശേഷം പുറപ്പെടുകയും ഇരുട്ടാകുന്നതുവരെ യാത്ര തുടരുകയും, പിന്നെ ഒരു സ്ഥലത്ത് ഇറങ്ങി മഗ്രിബ് നിസ്കരിക്കുകയും ചെയ്യും. പിന്നീട് അദ്ദേഹത്തിന്റെ രാത്രി ഭക്ഷണം കൊണ്ടു വരുവാൻ ആവശ്യപ്പെടുകയും തുടർന്ന് ഭക്ഷണം കഴിക്കുകയും ശേഷം ഇശാഅ് നിസ്കരിക്കുകയും ചെയ്യും, പിന്നീട് യാത്ര തുടരും. റസൂൽ(സ) ഇപ്രകാരമാണ് ചെയ്തിരുന്നത് എന്ന് പറയുകയും ചെയ്യുമായിരുന്നു. മറ്റൊരു നിവേദനത്തിൽ സന്ധ്യാവെളിച്ചം മായുന്ന വേളയിൽ അനസ്(റ) മഗ്രിബും ഇശാഉം ചേർത്ത് നിസ്കരിക്കും. ശേഷം ഇപ്രകാരം പറയും: റസൂൽ(സ) ഇങ്ങനെ ചെയ്യാറുണ്ടായിരുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 703, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=26), 1, 'وَفِي رِوَايَةٍ: أَنَّ أَنَسًا رَضِيَ اللهُ عَنْهُ كَانَ يَجْمَعُ بَيْنَهُمَا حِينَ يَغِيبُ الشَّفَقُ، وَيَقُولُ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ ذَلِكَ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ സന്ധ്യാവെളിച്ചം മായുന്ന വേളയിൽ അനസ്(റ) മഗ്രിബും ഇശാഉം ചേർത്ത് നിസ്കരിക്കും. ശേഷം ഇപ്രകാരം പറയും: റസൂൽ(സ) ഇങ്ങനെ ചെയ്യാറുണ്ടായിരുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمِنًى صَلَاةَ الْمُسَافِرِ وَأَبُو بَكْرٍ وَعُمَرُ وَعُثْمَانُ رَضِيَ اللهُ عَنْهُمْ ثَمَانِيَ سِنِينَ، أَوْ قَالَ: سِتَّ سِنِينَ، قَالَ حَفْصٌ - يَعْنِي ابْنَ عَاصِمٍ -: وَكَانَ ابْنُ عُمَرَ يُصَلِّي بِمِنًى رَكْعَتَيْنِ ثُمَّ يَأْتِي فِرَاشَهُ، فَقُلْتُ: أَيْ عَمِّ لَوْ صَلَّيْتَ بَعْدَهَا رَكْعَتَيْنِ؟ قَالَ: لَوْ فَعَلْتُ لَأَتْمَمْتُ الصَّلَاةَ. (م)', 'ഇബ്നുഉമർ(റ): നബി(സ) മിനായിൽ യാത്രക്കാരന്റെ നിസ്കാരം നിർവ്വഹിച്ചു. അതുപോലെ അബൂബക്ർ(റ), ഉമർ(റ), ഉസ്മാൻ(റ) എന്നിവർ എട്ട് വർഷങ്ങളിൽ അല്ലെങ്കിൽ ആറ് വർഷങ്ങളിൽ മിനായിൽ (ചുരുക്കി നിസ്കരിച്ചു). ഹഫ്സ് (ഇബ്നുആസിം) പറയുന്നു: ഇബ്നുഉമർ(റ) മിനായിൽ രണ്ട് റക്അത്ത് നിസ്കരിച്ച ശേഷം അദ്ദേഹം തന്റെ വിരിപ്പിൽ എത്തുമായിരുന്നു. അപ്പോൾ ഞാൻ ചോദിച്ചു. അല്ലയോ പിതൃവ്യാ, അതിന് ശേഷം താങ്കൾ രണ്ട് റക്അത്ത് കൂടി നിസ്കരിച്ചിരുന്നുവെങ്കിൽ? അദ്ദേഹം പറഞ്ഞു: ഞാൻ അങ്ങനെ ചെയ്യുമായിരുന്നുവെങ്കിൽ തീർച്ചയായും എനിക്ക് നിസ്കാരത്തെ പൂർത്തിയാക്കാമായിരുന്നു. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 704, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمِنًى - آمَنَ مَا كَانَ النَّاسُ وَأَكْثَرَهُ - رَكْعَتَيْنِ. وَفِي رِوَايَةٍ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمِنًى - أَكْثَرَ مَا كَانَ النَّاسُ وَآمَنَهُ - رَكْعَتَيْنِ. (خ,ن)', 'ഹാരിസ്ബിൻവഹബ് അൽഖുസാഈ(റ): ജനങ്ങളിൽ അധികവും എന്നത്തെക്കാളുമുപരി നിർഭയരായിരുന്ന അവസരത്തിൽ മിനായിൽ നബി(സ)യോടൊപ്പം ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. മറ്റൊരു നിവേദനത്തിൽ അദ്ദേഹം പറയുന്നു: ജനങ്ങളിൽ അധികപക്ഷവും തിരുമേനി(സ)യും ഏറ്റവും കൂടുതൽ നിർഭയരായിരുന്ന അവസ്ഥയിൽ മിനായിൽ വെച്ച് റസൂൽ(സ) ഞങ്ങളെ കൊണ്ട് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (ബു,ന)', 'حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ', 'ഹാരിസ്ബിൻവഹബ് അൽഖുസാഈ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 704, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=28), 1, 'وَفِي رِوَايَةٍ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمِنًى - أَكْثَرَ مَا كَانَ النَّاسُ وَآمَنَهُ - رَكْعَتَيْنِ. (خ,ن)', 'മറ്റൊരു നിവേദനത്തിൽ അദ്ദേഹം പറയുന്നു: ജനങ്ങളിൽ അധികപക്ഷവും തിരുമേനി(സ)യും ഏറ്റവും കൂടുതൽ നിർഭയരായിരുന്ന അവസ്ഥയിൽ മിനായിൽ വെച്ച് റസൂൽ(സ) ഞങ്ങളെ കൊണ്ട് രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. (ബു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمِنًى رَكْعَتَيْنِ، وَأَبِي بَكْرٍ وَعُمَرَ، وَمَعَ عُثْمَانَ صَدْرًا مِنْ إِمَارَتِهِ، ثُمَّ أَتَمَّهَا. (خ,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ)യോടൊപ്പവും, അബൂബക്റിനോടൊപ്പവും, ഉമറി(റ)നോടൊപ്പവും മിനയിൽ ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. ഉസ്മാനി(റ)ന്റെ കൂടെ അദ്ദേഹത്തിന്റെ നേതൃത്വത്തിന്റെ ആദ്യഘട്ടത്തിലും (ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചു), പിന്നെ അദ്ദേഹം പൂർണ്ണമാക്കി നിസ്കരിക്കുമായിരുന്നു. (ബു,ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 704, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، لَمَّا قِيلَ لَهُ: صَلَّى بِنَا عُثْمَانُ بْنُ عَفَّانَ رَضِيَ اللهُ عَنْهُ بِمِنًى أَرْبَعَ رَكَعَاتٍ، فَاسْتَرْجَعَ، ثُمَّ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمِنًى رَكْعَتَيْنِ، وَصَلَّيْتُ مَعَ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ بِمِنًى رَكْعَتَيْنِ، وَصَلَّيْتُ مَعَ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ بِمِنًى رَكْعَتَيْنِ، فَلَيْتَ حَظِّي مِنْ أَرْبَعِ رَكَعَاتٍ رَكْعَتَانِ مُتَقَبَّلَتَانِ. (خ,ن)', 'ഇബ്നുമസ്ഊദ്(റ): മിനായിൽ ഉസ്മാൻ(റ) ഞങ്ങൾക്ക് ഇമാമായി നാല് റക്അത്ത് നിസ്കരിച്ചുവല്ലോ എന്ന് അദ്ദേഹത്തോട് പറയപ്പെട്ടപ്പോൾ അദ്ദേഹം ''إنا لله وإنا إليه راجعون'' (നിശ്ചയം, ഞങ്ങൾ അല്ലാഹുവിനുള്ളതാണ് അവങ്കലേക്ക് തന്നെ മടങ്ങുകയും ചെയ്യും) എന്ന് ചൊല്ലിയ ശേഷം പറഞ്ഞു: റസൂലി(സ)നോടൊപ്പം മിനായിൽ ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചിരിക്കുന്നു. അബൂബക്റി(റ)നോടൊപ്പവും മിനായിൽ ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചിരിക്കുന്നു. ഉമർബിൻ ഖത്താബി(റ)നോടൊപ്പവും മിനായിൽ ഞാൻ രണ്ട് റക്അത്ത് നിസ്കരിച്ചിരിക്കുന്നു. നാല് റക്അത്തിനെക്കാൾ സ്വീകരിക്കപ്പെട്ട രണ്ട് റക്അത്ത് എന്റെ സൗഭാഗ്യമായിരുന്നെങ്കിൽ നന്നായിരുന്നു. (ബു,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 704, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ حَفْصِ بْنِ عَاصِمٍ قَالَ: صَحِبْتُ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا فِي طَرِيقِ مَكَّةَ، قَالَ: فَصَلَّى لَنَا الظُّهْرَ رَكْعَتَيْنِ، ثُمَّ أَقْبَلَ وَأَقْبَلْنَا مَعَهُ حَتَّى جَاءَ رَحْلَهُ، وَجَلَسَ وَجَلَسْنَا مَعَهُ، فَحَانَتْ مِنْهُ الْتِفَاتَةٌ نَحْوَ حَيْثُ صَلَّى، فَرَأَى نَاسًا قِيَامًا، فَقَالَ: مَا يَصْنَعُ هَؤُلَاءِ؟ قُلْتُ: يُسَبِّحُونَ، قَالَ: لَوْ كُنْتُ مُسَبِّحًا لَأَتْمَمْتُ صَلَاتِي، يَا ابْنَ أَخِي إِنِّي صَحِبْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللهُ، وَصَحِبْتُ أَبَا بَكْرٍ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللهُ، وَصَحِبْتُ عُمَرَ رَضِيَ اللهُ عَنْهُ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللهُ عَزَّوَجَلَّ، ثُمَّ صَحِبْتُ عُثْمَانَ فَلَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى قَبَضَهُ اللهُ عَزَّوَجَلَّ، وَقَدْ قَالَ اللهُ تَعَالَى: {لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللهِ أُسْوَةٌ حَسَنَةٌ} [الأحزاب: ٢١]. (ق,د,ن,جه)', 'ഹഫ്സിബിൻ ആസിം(റ): മക്കയുടെ വഴിയിൽ ഇബ്നുഉമർ(റ)വുമായി ഞാൻ സഹവസിച്ചു. നിവേദകൻ പറയുന്നു: ദുഹ്ർ നമസ്കാരം രണ്ട് റക്അത്തായി അദ്ദേഹം ഞങ്ങളെ കൊണ്ട് നിർവ്വഹിച്ചു. പിന്നീടദ്ദേഹം മുന്നോട്ട് പോയി. അദ്ദേഹത്തോടൊപ്പം ഞങ്ങളും മുന്നോട്ട് പോയി. അദ്ദേഹത്തിന്റെ വാഹനത്തിന്റെ അടുക്കൽ എത്തിയപ്പോൾ അദ്ദേഹം ഇരിക്കുകയും അദ്ദേഹത്തോടൊപ്പം ഞങ്ങളും ഇരിക്കുകയും ചെയ്തു. ശേഷം നിസ്കരിച്ച സ്ഥലത്തേക്ക് ഒന്ന് തിരിഞ്ഞു നോക്കിയപ്പോൾ ചിലർ നിൽക്കുന്നതായി കണ്ടു. അദ്ദേഹം ചോദിച്ചു. ആ കൂട്ടർ എന്തു ചെയ്യുന്നു? ഞാൻ പറഞ്ഞു: അവർ സുന്നത്ത് നിസ്കരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: ഞാൻ സുന്നത്ത് നിസ്കരിക്കുന്നവനായിരുന്നുവെങ്കിൽ തീർച്ചയായും നിസ്കാരത്തെ ഞാൻ പൂർത്തീകരിക്കുമായിരുന്നു. എന്റെ സഹോദര പുത്രാ! യാത്രയിൽ ഞാൻ റസൂലി(സ)നെ സഹവസിച്ചിട്ടുണ്ട്. മരിക്കുന്നത് വരെ രണ്ട് റക്അത്തിനേക്കാൾ കൂടുതൽ അവിടുന്ന് അധികരിപ്പിച്ചിട്ടില്ല. അബൂബക്റി(റ)നോടൊപ്പം (ഞാൻ യാത്രയിൽ) സഹവസിച്ചിരുന്നു. വഫാത്താകുന്നത് വരെ രണ്ട് റക്അത്തിനേക്കാൾ കൂടുതൽ അവിടുന്ന് അധികരിപ്പിച്ചിട്ടില്ല. ഉമറി(റ)നോടൊപ്പവും (ഞാൻ യാത്രയിൽ) സഹവസിച്ചിരുന്നു. വഫാത്താകുന്നത് വരെ രണ്ട് റക്അത്തിനേക്കാൾ കൂടുതൽ അദ്ദേഹവും അധികരിപ്പിച്ചിട്ടില്ല. ശേഷം ഉസ്മാൻ(റ)വിനോടൊപ്പവും ഞാൻ (യാത്രയിൽ) സഹവസിച്ചിരുന്നു. വഫാതാകുന്നതുവരെ അദ്ദേഹവും രണ്ട് റക്അതിനേക്കാൾ അധികരിപ്പിച്ചിട്ടില്ല. അല്ലാഹു പറഞ്ഞിരിക്കുന്നു. തീർച്ചയായും അല്ലാഹുവിന്റെ റസൂലിൽ നിങ്ങൾക്ക് നല്ല മാതൃകയുണ്ട്. (അൽ അഹ്സാബ്: 21) (മു,ദ,ന,ജ)', 'حَفْصِ بْنِ عَاصِمٍ قَالَ', 'ഹഫ്സിബിൻ ആസിം(റ)', null, null, array['ق','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], 'الأحزاب: ٢١', null, 705, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ: أَنَّهُ سَأَلَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: هَلْ رُخِّصَ لِلنِّسَاءِ أَنْ يُصَلِّينَ عَلَى الدَّوَابِّ؟ قَالَتْ: لَمْ يُرَخَّصْ لَهُنَّ فِي ذَلِكَ فِي شِدَّةٍ وَلَا رَخَاءٍ، قَالَ: هَذَا فِي الْمَكْتُوبَةِ. (د)', 'അത്വാഉബ്നു അബീറബാഹ്(റ): അദ്ദേഹം ആയിശ(റ)യോട് ചോദിച്ചു: സ്ത്രീകൾക്ക് വാഹനത്തിൽ നിസ്കിരക്കുവാൻ പ്രത്യേക അനുവാദം നൽകപ്പെട്ടിട്ടുണ്ടോ? മഹതി പറഞ്ഞു: ബുദ്ധിമുട്ടുള്ള അവസ്ഥയിലും സൗകര്യമുള്ള അവസ്ഥയിലും ഇക്കാര്യത്തിൽ സ്ത്രീകൾക്ക് പ്രത്യേക അനുവാദം നൽകപ്പെട്ടിട്ടില്ല. അത്വാഅ് പറയുന്നു: ഇത് ഫർള് നിസ്കാരത്തിന്റെ കാര്യത്തിലാണ്. (ദ)', 'عَطَاءِ بْنِ أَبِي رَبَاحٍ', 'അത്വാഉബ്നു അബീറബാഹ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا ارْتَحَلَ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ إِلَى وَقْتِ الْعَصْرِ، ثُمَّ نَزَلَ فَجَمَعَ بَيْنَهُمَا. فَإِنْ زَاغَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ: صَلَّى الظُّهْرَ، ثُمَّ رَكِبَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ: وَيُؤَخِّرُ الْمَغْرِبَ حَتَّى يَجْمَعَ بَيْنَهَا وَبَيْنَ الْعِشَاءِ حِينَ يَغِيبُ الشَّفَقُ. (ق,د,ن)', 'അനസ്ബിനുമാലിക്(റ): സൂര്യൻ ആകാശ മധ്യത്തിൽനിന്നും തെറ്റുന്നതിന് മുമ്പ് യാത്രതുടങ്ങുമ്പോൾ റസൂൽ(സ) ളുഹ്ർ, അസ്റിന്റെ സമയത്തേക്ക് പിന്തിക്കുകയും പിന്നീട് (വാഹനത്തിൽനിന്ന്) ഇറങ്ങി അത് രണ്ടും (ദുഹ്റും, അസ്റും) ചേർത്ത് നിസ്കരിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഇനി തിരുമേനി(സ) പുറപ്പെടുന്നതിന് മുമ്പ് സൂര്യൻ ആകാശമദ്ധ്യത്തിൽ നിന്നും തെറ്റിയാൽ ളുഹ്റ് നിസ്കരിക്കുകയും തുടർന്ന് തിരുമേനി(സ) വാഹനത്തിൽ കയറുകയും ചെയ്യുമായിരുന്നു. മറ്റൊരു നിവേദനപ്രകാരം, ഇശാഇനോടൊപ്പം നിസ്കരിക്കുന്നതിന് വേണ്ടി സന്ധ്യാവെളിച്ചം മായുന്നത് വരെ തിരുമേനി(സ) മഗ്രിബിനെ പിന്തിക്കുകയും ചെയ്യുമായിരുന്നു എന്നാണുള്ളത്. (ബു,മു,ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബിനുമാലിക്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=33), 1, 'وَفِي رِوَايَةٍ: وَيُؤَخِّرُ الْمَغْرِبَ حَتَّى يَجْمَعَ بَيْنَهَا وَبَيْنَ الْعِشَاءِ حِينَ يَغِيبُ الشَّفَقُ. (ق,د,ن)', 'മറ്റൊരു നിവേദനപ്രകാരം, ഇശാഇനോടൊപ്പം നിസ്കരിക്കുന്നതിന് വേണ്ടി സന്ധ്യാവെളിച്ചം മായുന്നത് വരെ തിരുമേനി(സ) മഗ്രിബിനെ പിന്തിക്കുകയും ചെയ്യുമായിരുന്നു എന്നാണുള്ളത്. (ബു,മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا اعْتَمَرَتْ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ، حَتَّى إِذَا قَدِمَتْ مَكَّةَ قَالَتْ: يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ وَأُمِّي، قَصَرْتَ وَأَتْمَمْتُ وَأَفْطَرْتَ وَصُمْتُ؟ قَالَ: "أَحْسَنْتِ يَا عَائِشَةُ". وَمَا عَابَ عَلَيَّ. (ن)', 'ആഇശ(റ): റസൂലി(സ)നോടൊപ്പം മദീനയിൽ നിന്നും മക്കായിലേക്ക് അവർ ഉംറക്കായി പുറപ്പെട്ടു. മക്കയിലെത്തിയപ്പോൾ അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ! എന്റെ പിതാവും മാതാവും അങ്ങേയ്ക്ക് അർപ്പണമാകട്ടെ. അങ്ങ് ചുരുക്കി നിസ്കരിച്ചു. ഞാൻ പൂർത്തിയാക്കി നിസ്കരിച്ചു. അങ്ങ് നോമ്പ് ഒഴിവാക്കി. ഞാൻ നോമ്പ് അനുഷ്ടിച്ചു? അവിടുന്ന് പറഞ്ഞു. "ആയിശാ, നീ നല്ലത് ചെയ്തു." തിരുമേനി(സ) എന്നെ കുറ്റം പറഞ്ഞില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقَامَ بِمَكَّةَ خَمْسَةَ عَشَرَ يُصَلِّي رَكْعَتَيْنِ رَكْعَتَيْنِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പതിനഞ്ച് ദിവസം മക്കയിൽ താമസിച്ചപ്പോൾ ഈരണ്ട് റക്അത്ത് ആയിരുന്നു നിസ്കരിച്ചിരുന്നത്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ الْعَلَاءِ بْنِ الْحَضْرَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَمْكُثُ الْمُهَاجِرُ بَعْدَ قَضَاءِ نُسُكِهِ ثَلَاثًا". (ن)', 'അലാഇബിനുഹളറമി(റ): റസൂൽ(സ) പറഞ്ഞു: "യാത്രക്കാരന് (ഹാജി) ഹജ്ജ് സംബന്ധമായ പ്രവർത്തനങ്ങൾ പൂർത്തിയാക്കിയശേഷം മൂന്നു ദിവസം താമസിക്കാവുന്നതാണ്." (ന)', 'الْعَلَاءِ بْنِ الْحَضْرَمِيِّ', 'അലാഇബിനുഹളറമി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ جابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَارَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَتَى عَرَفَةَ، فَوَجَدَ الْقُبَّةَ قَدْ ضُرِبَتْ لَهُ بِنمرَةَ فَنَزَلَ بِهَا، حَتَّى إذَا زَاغَتِ الشَّمْسُ أَمَرَ بالْقَصْواءِ فَرُحِّلَتْ لَهُ، حَتَّى إذَا انْتَهَى إلَى بَطْنِ الْوَادِي خَطَبَ النَّاسَ، ثُمَّ أَذَّنَ بِلالٌ، ثُمَّ أَقَامَ فَصَلَّى الظُّهْرَ، ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ، وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): പ്രവാചകൻ(സ) (മിനായിൽനിന്നും) അറഫായിലേക്കു വരികയും അവിടുത്തേക്കു വേണ്ടി കൂടാരം നിർമ്മിക്കപ്പെട്ട ''നംറ''യിൽ ഇറങ്ങുകയും ചെയ്തു. സൂര്യൻ മധ്യത്തിൽനിന്നു നീങ്ങിയപ്പോൾ അവിടുന്ന് (സവാരിചെയ്യാൻ വേണ്ടി) ''ഖുസ്വാ''(പെൺഒട്ടകം)യെ ആവശ്യപ്പെടുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ)ക്കുവേണ്ടി അതിനെ യാത്രക്കു സജ്ജമാക്കിക്കൊടുത്തു. അങ്ങനെ അവിടുന്ന് (അറഫാ)താഴ്വരിൽ പ്രവേശിച്ചപ്പോൾ അവിടുന്ന് ജനങ്ങളെ അഭിസംബോധന ചെയ്തുകൊണ്ട് പ്രസംഗിച്ചു. പിന്നെ ബിലാൽ(റ) ബാങ്കുവിളിക്കുകയും ശേഷം ഇഖാമത്തു വിളിക്കുകയും, അങ്ങനെ നബി(സ) ദുഹ്ർ നിസ്കാരം നിർവ്വഹിക്കുകയും, ശേഷം ഇഖാമത്ത് വിളിക്കുകയും അസ്ർ നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്തു. അവക്കിടയിൽ തിരുമേനി(സ) ഒന്നും നിസ്കരിച്ചിട്ടില്ല. (ന)', 'جابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ مُؤَذِّنَهُ قَالَ: الصَّلاةُ، قَالَ: سِرْ، سِرْ، حَتَّى إذَا كَانَ قَبْلَ غُيُوبِ الشَّفَقِ نَزَلَ فَصَلَّى الْمَغْرِبَ، ثُمَّ انْتَظَرَ حَتَّى غَابَ الشَّفَقُ وَصَلَّى الْعِشَاءَ، ثُمَّ قَالَ، إنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إذَا عَجِلَ بِهِ أَمْرٌ صَنَعَ مِثْلَ الَّذِي صَنَعْتُ. فَسَارَ فِي ذَلِكَ الْيَوْمِ وَاللَّيْلَةِ مَسِيرَةَ ثَلاثٍ. وَفِي رِوَايَةٍ: حَتَّى إذَا كَانَ عِنْدَ ذَهَابِ الشَّفَقِ نَزَلَ فَجَمَعَ بَيْنَهُمَا. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹത്തിന്റെ മുഅദ്ദിൻ നിസ്കാരം എന്ന് പറഞ്ഞു, ഇബ്നുഉമർ(റ) പറഞ്ഞു: നടക്കൂ! നടക്കൂ!. സന്ധ്യാവെളിച്ചം മായുന്നതിന് അടുത്തെത്തിയപ്പോൾ അദ്ദേഹം (വാഹനത്തിൽനിന്ന്) ഇറങ്ങുകയും മഗ്രിബ് നിസ്കരിക്കുകയും സന്ധ്യാവെളിച്ചം മായുന്നത് വരെ കാത്തിരിക്കുകയും ഇശാഅ് നിസ്കരിക്കുകയും ചെയ്തു. തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: റസൂലി(സ)ന് വല്ല കാര്യത്തിലും ധൃതിയുണ്ടാകുന്നുവെങ്കിൽ ഞാൻ പ്രവർത്തിച്ചത് പോലെ അവിടുന്ന് പ്രവർത്തിക്കുമായിരുന്നു. തുടർന്ന് അദ്ദേഹം ആ പകലിലും രാത്രിയിലും മൂന്ന് (ദിവസത്തെ) ദൂരം യാത്ര ചെയ്തു. മറ്റൊരു നിവേദനം: (യാത്ര തുടരുകയും) സന്ധ്യാവെളിച്ചം നീങ്ങാറായപ്പോൾ ഇറങ്ങി മഗ്രിബും ഇശാഉം ചേർത്ത് നിസ്കരിക്കുകയും ചെയ്തു. (ദ)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=38), 1, 'وَفِي رِوَايَةٍ: حَتَّى إذَا كَانَ عِنْدَ ذَهَابِ الشَّفَقِ نَزَلَ فَجَمَعَ بَيْنَهُمَا. (د)', 'മറ്റൊരു നിവേദനം: (യാത്ര തുടരുകയും) സന്ധ്യാവെളിച്ചം നീങ്ങാറായപ്പോൾ ഇറങ്ങി മഗ്രിബും ഇശാഉം ചേർത്ത് നിസ്കരിക്കുകയും ചെയ്തു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ جابِرٍ رَضِيَ اللهُ عَنْهُ :أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غابَتْ لَهُ الشَّمْسُ بِمَكَّةَ، فَجمَعَ بَيْنَهُما بِسَرِفٍ. (د,ن)', 'ജാബിർ(റ): റസൂൽ(സ) മക്കയിയിലായിരിക്കെ സൂര്യൻ അസ്തമിച്ചു. അങ്ങിനെ സരിഫ് എന്ന സ്ഥലത്ത് വെച്ച് അവ രണ്ടും (മഗ്രിബും, ഇശാഉം) അദ്ദേഹം ചേർത്ത് നിസ്കരിച്ചു. (ദ,ന)', 'جابِرٍ', 'ജാബിർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ هِشَامِ بْنِ سَعْدٍ قَالَ: بَيْنَهُمَا عَشَرَةُ أَمْيَالٍ. يَعْنِي: بَيْنَ مَكَّةَ وَسَرِفٍ. (د)', 'ഹിഷാമിബിനു സഅദ്: മക്കക്കും സരിഫിനും ഇടയിൽ പത്ത് മൈൽ ദൂരമുണ്ട്. (ദ)', 'هِشَامِ بْنِ سَعْدٍ قَالَ', 'ഹിഷാമിബിനു സഅദ്', null, null, array['د']::text[], array['ദ']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَبْدِ اللهِ بْنِ دِينَارٍ قَالَ: غَابَتِ الشَّمْسُ وَأَنَا عِنْدَ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، فَسِرْنَا، فَلَمَّا رَأَيْنَاهُ قَدْ أَمْسَى قُلْنَا: الصَّلاةَ، فَسَارَ حَتَّى غَابَ الشَّفَقُ وَتَصَوَّبَتِ النُّجُومُ، ثُمَّ إنَّهُ نَزَلَ فَصَلَّى الصَّلاتَيْنِ جَمِيعًا، ثُمَّ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا جَدَّ بِهِ السَّيْرُ صَلَّى صَلاتِي هَذِهِ. يَقُولُ: يَجْمَعُ بَيْنَهُمَا بَعْدَ لَيْلٍ. وَفِي رِوَايَةٍ: أَنَّ الْجَمْعَ بَيْنَهُمَا مِنِ ابْنِ عُمَرَ كَانَ بَعْدَ غُيُوبِ الشَّفَقِ. (د)', 'അബ്ദുല്ലാഹിബ്നു ദീനാർ(റ): ഞാൻ അബ്ദുല്ലാഹിബിനു ഉമറി(റ)ന്റെ അടുത്തായിരിക്കുമ്പോൾ സൂര്യൻ മറഞ്ഞു (അസ്തമിച്ചു). തുടർന്ന് ഞങ്ങൾ സഞ്ചരിച്ചു. സമയം വൈകുന്നേരമായി എന്ന് മനസ്സിലാക്കിയ പ്പോൾ, ഞങ്ങൾ ''നിസ്കാരം'' എന്ന് പറഞ്ഞു. പക്ഷേ, സന്ധ്യാവെളിച്ചം മാഞ്ഞ് നക്ഷത്രങ്ങൾ വ്യക്തമാകുന്നത് വരെ അദ്ദേഹം സഞ്ചരിച്ചു. പിന്നെ ഇറങ്ങി രണ്ട് നിസ്കാരങ്ങളും (മഗ്രിബും, ഇശാഉം) ഒരുമിച്ച് നിസ്കരിച്ചു. പിന്നെ അദ്ദേഹം പറഞ്ഞു. റസൂൽ(സ) യാത്രയിൽ വല്ല ധൃതിയും അനുഭവപ്പെട്ടാൽ എന്റെ ഈ നിസ്കാരം നിർവ്വഹിക്കുന്നതായി ഞാൻ കണ്ടിരിക്കുന്നു. അദ്ദേഹം പറയുന്നു: രാത്രി (വൈകിയ) ശേഷം ഈ രണ്ട് നിസ്കാരങ്ങളും ഒരുമിച്ച് നിസ്കരിക്കും. മറ്റൊരു റിപ്പോർട്ടിൽ: ഇബ്നുഉമർ(റ) ഇവ ചേർത്ത് നിസ്കരിച്ചിരുന്നത് സന്ധ്യാവെളിച്ചം അസ്തമിച്ച ശേഷമായിരുന്നു. (ദ)', 'عَبْدِ اللهِ بْنِ دِينَارٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ദീനാർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 707, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=41), 1, 'وَفِي رِوَايَةٍ: أَنَّ الْجَمْعَ بَيْنَهُمَا مِنِ ابْنِ عُمَرَ كَانَ بَعْدَ غُيُوبِ الشَّفَقِ. (د)', 'മറ്റൊരു നിവേദനിൽ: ഇബ്നുഉമർ(റ) ഇവ ചേർത്ത് നിസ്കരിച്ചിരുന്നത് സന്ധ്യാവെളിച്ചം അസ്തമിച്ച ശേഷമായിരുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: اسْتُصْرِخَ عَلَى صَفِيَّةَ وَهُوَ بِمَكَّةَ، فَسَارَ حَتَّى غَرُبَتِ الشَّمْسُ وَبَدَتِ النُّجُومُ، فَقَالَ: إنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إذَا عَجِلَ بِهِ أَمْرٌ فِي سَفَرٍ جَمَعَ بَيْنَ هَاتَيْنِ الصَّلاتَيْنِ، فَسَارَ حَتَّى غَابَ الشَّفَقُ، فَنَزَلَ فَجَمَعَ بَيْنَهُمَا. (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം മക്കയിലായിരിക്കുമ്പോൾ സ്വഫിയ(റ)യുടെ കാര്യത്തിൽ അദ്ദേഹത്തോട് സഹായശബ്ദമുയർത്തപ്പെട്ടു. (സഹായത്തിന് വേണ്ടി നിലവിളിച്ചു) അങ്ങനെ സൂര്യനസ്തമിച്ച് നക്ഷത്രങ്ങൾ പ്രത്യക്ഷപ്പെടുന്നത് വരെ അദ്ദേഹം യാത്ര ചെയ്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ)ക്ക് യാത്രയിൽ ധൃതി അനുഭവപ്പെട്ടാൽ ഈ രണ്ട് നിസ്കാരങ്ങൾ(മഗ്രിബ്, ഇശാഅ്) ഒരുമിച്ച് നിർവ്വഹിക്കുമായിരുന്നു. തുടർന്ന് അദ്ദേഹം വെളിച്ചം മായുന്നത് വരെ യാത്ര തുടരുകയും, ഇറങ്ങി രണ്ട് നിസ്കാരങ്ങളും ഒരുമിച്ച് നിർവ്വഹിക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 708, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا جَمَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ قَطُّ فِي السَّفَرِ إلَّا مَرَّةً. قَالَ أبو دَاوُدَ: وَهَذَا يُرْوَى مَوْقُوفًا عَلَى ابْنِ عُمَرَ: أَنَّهُ لَمْ يُرَ جَمَعَ بَيْنَهُمَا قَطُّ إلَّا لَيْلَةً يَعْنِي لَيْلَةَ اسْتُصْرِخَ عَلَى صَفِيَّةَ. (د)', 'ഇബ്നുഉമർ(റ): യാത്രയിൽ ഒരു പ്രാവശ്യം മാത്രമല്ലാതെ മഗ്രിബ് ഇശാഅ് നിസ്കാരങ്ങൾക്കിടയിൽ റസൂൽ(സ) ചേർത്ത് നിസ്കരിച്ചിട്ടില്ല. അബൂദാവൂദ്(റ) പറയുന്നു: ഇത് ഇബ്നുഉമറി(റ)ൽ എത്തിനിൽക്കുന്ന നിവേദനമാണ്. അതായത് സഫിയ(റ)യുമായി ബന്ധപ്പെട്ട് സഹായശബ്ദമുയർത്തപ്പെട്ട രാത്രിയിലല്ലാതെ മഗരിബ് ഇശാഅ് നിസ്കാരങ്ങൾക്കിടയിൽ ചേർത്ത് നിസ്കരിക്കുന്നതായി ഇബ്നുഉമർ(റ)യെ കാണപ്പെട്ടിട്ടില്ല. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 708, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي الطُّفَيْلِ عَامِرِ بْنِ وَاثِلَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ مُعَاذَ بْنَ جَبَلٍ رَضِيَ اللهُ عَنْهُ أَخْبَرَهُ: أَنَّهُمْ خَرَجُوا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ، فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَالْمَغْرِبِ وَالْعِشَاءِ. فَأَخَّرَ الصَّلاةَ يَوْمًا، ثُمَّ خَرَجَ فَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، ثُمَّ دَخَلَ، ثُمَّ خَرَجَ فَصَلَّى الْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزْوَةِ تَبُوكَ: إذَا زَاغَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ جَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَإِنْ يَرْتَحِلْ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ حَتَّى يَنْزِلَ لِلْعَصْرِ. وَفِي الْمَغْرِبِ مِثْلُ ذَلِكَ: إنْ غَابَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، وَإِنْ يَرْتَحِلْ قَبْلَ أَنْ تَغِيبَ الشَّمْسُ أَخَّرَ الْمَغْرِبَ حَتَّى يَنْزِلَ لِلْعِشَاءِ، ثُمَّ جَمَعَ بَيْنَهُمَا. وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزْوَةِ تَبُوكَ: إذَا ارْتَحَلَ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ حَتَّى يَجْمَعَهَا إلَى الْعَصْرِ فَيُصَلِّيَهُمَا جَمِيعًا، وَإِذَا ارْتَحَلَ بَعْدَ زَيْغِ الشَّمْسِ صَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا ثُمَّ سَارَ. وَكَانَ إذَا ارْتَحَلَ قَبْلَ الْمَغْرِبِ أَخَّرَ الْمَغْرِبَ حَتَّى يُصَلِّيَهَا مَعَ الْعِشَاءِ، وَإِذَا ارْتَحَلَ بَعْدَ الْمَغْرِبِ عَجَّلَ الْعِشَاءَ فَصَلَّاهَا مَعَ الْمَغْرِبِ. (م,د,ت,ن,جه)', 'ആബൂതുഫൈൽ ആമിർബിൻ വാസില(റ): മുആദ്ബിൻ ജബൽ(റ) അദ്ദേഹത്തെ അറിയിച്ചു അവർ (സ്വഹാബികൾ) റസൂലി(സ)നോടൊപ്പം തബൂക് യുദ്ധത്തിന് പുറപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) ളുഹ്റും അസ്വ്റും തമ്മിൽ ചേർത്തും, മഗ്രിബും ഇശാഉം തമ്മിൽ ചേർത്തും നിസ്കരിക്കുമായിരുന്നു. ഒരു ദിവസത്തിൽ അവിടുന്ന് നിസ്കാരത്തെ പിന്തിച്ചു. പിന്നീട് തിരുമേനി(സ) പുറപ്പെടുകയും ളുഹ്റും അസ്റും ചേർത്ത് നിസ്കരിക്കുകയും ചെയ്തു. പിന്നെ തിരുമേനി(സ) പ്രവേശിച്ചു ശേഷം പുറപ്പെടുകയും മഗരിബും ഇശാഉം ചേർത്ത് നിസ്കരിക്കുകയും ചെയ്തു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=44), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزْوَةِ تَبُوكَ: إذَا زَاغَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ جَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ، وَإِنْ يَرْتَحِلْ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ حَتَّى يَنْزِلَ لِلْعَصْرِ. وَفِي الْمَغْرِبِ مِثْلُ ذَلِكَ: إنْ غَابَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، وَإِنْ يَرْتَحِلْ قَبْلَ أَنْ تَغِيبَ الشَّمْسُ أَخَّرَ الْمَغْرِبَ حَتَّى يَنْزِلَ لِلْعِشَاءِ، ثُمَّ جَمَعَ بَيْنَهُمَا.', 'മറ്റൊരു നിവേദന പ്രകാരം: റസൂൽ(സ) തബൂക്ക് യുദ്ധത്തിലായിരുന്നു. അവിടുന്ന് യാത്ര പുറപ്പെടുന്നതിന് മുമ്പ് സൂര്യൻ ആകാശമദ്ധ്യത്തിൽനിന്നു തെറ്റിയാൽ ളുഹ്റും, അസ്റും അവിടുന്ന് ചേർത്ത് നിസ്കരിക്കുമായിരുന്നു. സൂര്യൻ ആകാശമദ്ധ്യത്തിൽനിന്നും തെറ്റുന്നതിന് മുമ്പാണ് അവിടുത്തെ പുറപ്പെടലെങ്കിൽ അസ്വർ നിസ്കാരത്തിന് ഇറങ്ങുന്നതുവരെ ളുഹറിനെ അവിടുന്ന് പിന്തിക്കുമായിരുന്നു. മഗ്രിബിലും അപ്രകാരം തന്നെ. അവിടുന്ന് പുറപ്പെടുന്നതിന് മുമ്പ് സൂര്യനസ്തമിച്ചാൽ മഗ്രിബും ഇശാഉം (മഗ്രിബിന്റെ സമയത്ത്) ചേർത്ത് നിസ്കരിക്കുമായിരുന്നു. മഗ്രിബിന് മുമ്പാണ് പുറപ്പെടുന്നതെങ്കിൽ മഗ്രിബിനെ അവിടുന്ന് ഇശാഅ് നമസ്കാരത്തിന് ഇറങ്ങുന്നതുവരെ പിന്തിക്കുകയും പിന്നീട് രണ്ടും ചേർത്ത് നിസ്കിരക്കുകയും ചെയ്യുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=44), 2, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزْوَةِ تَبُوكَ: إذَا ارْتَحَلَ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ حَتَّى يَجْمَعَهَا إلَى الْعَصْرِ فَيُصَلِّيَهُمَا جَمِيعًا، وَإِذَا ارْتَحَلَ بَعْدَ زَيْغِ الشَّمْسِ صَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا ثُمَّ سَارَ. وَكَانَ إذَا ارْتَحَلَ قَبْلَ الْمَغْرِبِ أَخَّرَ الْمَغْرِبَ حَتَّى يُصَلِّيَهَا مَعَ الْعِشَاءِ، وَإِذَا ارْتَحَلَ بَعْدَ الْمَغْرِبِ عَجَّلَ الْعِشَاءَ فَصَلَّاهَا مَعَ الْمَغْرِبِ. (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനപ്രകാരം: നബി(സ) തബൂക്ക് യുദ്ധവേളയിലായിരുന്നു. സൂര്യൻ മധ്യാഹ്നത്തിൽ നിന്നും നീങ്ങുന്നതിന് മുമ്പാണ് തിരുമേനി(സ) പുറപ്പെടുന്നതെങ്കിൽ അസ്റിലേക്ക് ചേർക്കുവാനായി അവിടുന്ന് ളുഹ്റിനെ പിന്തിക്കുകയും രണ്ടിനെയും ചേർത്ത് നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. സൂര്യൻ മധ്യാഹ്നത്തിൽ നിന്നും നീങ്ങിയതിന് ശേഷമാണ് പുറപ്പെടുന്നതെങ്കിൽ അവിടുന്ന് ളുഹ്റിനെയും അസ്റിനെയും (ളുഹ്റിന്റെ സമയത്ത്) ചേർത്ത് നിസ്കരിക്കുകയും പിന്നീട് പുറപ്പെടുകയും ചെയ്യുമായിരുന്നു. മഗരിബിന് മുമ്പാണ് അവിടുത്തെ പുറപ്പാടെങ്കിൽ മഗ്രിബിനെ പിന്തിപ്പിച്ച് ഇശാഇനോട് ചേർത്ത് നിസ്കരിക്കുമായിരുന്നു. മഗ്രിബിന് ശേഷമാണ് അവിടുത്തെ യാത്രയെങ്കിൽ ഇശാഇനെ നേരത്തെയാക്കി മഗ്രിബിനോടൊപ്പം നിസ്കരിക്കുമായിരുന്നു. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ فِي السَّفَرِ، مِنْ غَيْرِ أَنْ يُعْجِلَهُ شَيْءٌ، وَلَا يَطْلُبُهُ عَدُوٌّ، وَلَا يَخَافُ شَيْئًا. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒന്നിനെയും ഭയപ്പെടാത്ത അവസരങ്ങളിലും, ശത്രു തിരുമേനി(സ)യെ അന്വേഷിക്കാത്തതും ഒരു നിലയിലുമുള്ള ധൃതിയില്ലാത്തതുമായ യാത്രാവേളയിലും റസൂൽ(സ) മഗ്രിബും ഇശാഉം ചേർത്ത് നിസ്കരിക്കുമായിരുന്നു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَحِبْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَمَانِيَةَ عَشَرَ سَفَرًا، فَمَا رَأَيْتُهُ تَرَكَ رَكْعَتَيْنِ إذَا زَاغَتِ الشَّمْسُ قَبْلَ الظُّهْرِ. (د,ت)', 'ബറാഅ്ബ്നു ആസിബ്(റ): റസൂലു(സ)മായി പതിനെട്ട് യാത്രയിൽ ഞാൻ സഹവസിച്ചു. ഉച്ച തിരിഞ്ഞാൽ ളുഹറിനു മുമ്പുള്ള രണ്ട് റക്അത്ത് ഉപേക്ഷിച്ചതായി അവിടുത്തെ ഞാൻ കണ്ടിട്ടില്ല. (ദ,തു)', 'الْبَرَاءِ بْنِ عَازِبٍ الْأَنْصَارِيِّ', 'ബറാഅ്ബ്നു ആസിബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: لَا يَزِيدُ فِي السَّفَرِ عَلَى رَكْعَتَيْنِ، لَا يُصَلِّي قَبْلَهَا وَلَا بَعْدَهَا. فَقِيلَ لَهُ: مَا هَذَا؟ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം യാത്രയിൽ രണ്ട് റക്അത്തിൽ അധികം നിസ്കരിക്കുമായിരുന്നില്ല. അതിന് മുമ്പും പിമ്പും അദ്ദേഹം നിസ്കരിച്ചിരുന്നുമില്ല. അപ്പോൾ അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. താങ്കൾ എന്താണ് ഇങ്ങനെ ചെയ്യുന്നത്? (എന്താണ് സുന്നത്ത് നിസ്കാരം നിർവ്വഹിക്കാത്തത്?) അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം പ്രവർത്തിക്കുന്നതായി ഞാൻ കണ്ടിരിക്കുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 709, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ وَالْعَصْرَ جَمِيعًا، وَالْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا، فِي غَيْرِ خَوْفٍ وَلَا سَفَرٍ. قَالَ مَالِكٌ: أَرَى ذَلِكَ كَانَ فِي مَطَرٍ. وَفِي رِوَايَةٍ: جَمَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ بِالْمَدِينَةِ، مِنْ غَيْرِ خَوْفٍ وَلَا مَطَرٍ. فَقِيلَ لِابْنِ عَبَّاسٍ: مَا أَرَادَ إلَى ذَلِكَ؟ قَالَ: أَرَادَ أَنْ لَا يُحْرِجَ أُمَّتَهُ. وَفِي رِوَايَةٍ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ ثَمَانِيًا وَسَبْعًا: الظُّهْرَ وَالْعَصْرَ، وَالْمَغْرِبَ وَالْعِشَاءَ. وَفِي رِوَايَةٍ: فِي غَيْرِ مَطَرٍ. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബിനു അബ്ബാസ്(റ): റസൂൽ(സ) ളുഹ്റും അസ്റും ചേർത്ത് നിസ്കരിച്ചു. മഗ്രിബും ഇശായും ചേർത്ത് നിസ്കരിച്ചു. (ശത്രു) ഭയം കൂടാതെയും യാത്രയില്ലാതെയും. ഇമാം മാലിക്(റ) പറയുന്നു. മഴയുള്ളപ്പോഴാണ് ഇതുണ്ടായതെന്ന് ഞാൻ കരുതുന്നു. മറ്റൊരു നിവേദനപ്രകാരം: മഴയോ, (ശത്രു) ഭയമോ കൂടാതെ മദീനായിൽവെച്ച് ളുഹറും അസറും മഗ്രിബും ഇശാഉം റസൂൽ(സ) ഒരുമിച്ച് നിസ്കരിച്ചു. ഇബ്നുഅബ്ബാസി(റ)നോട് ചോദിക്കപ്പെട്ടു. അതിനാൽ തിരുമേനി(സ) ഉദ്ദേശിച്ചതെന്താണ്. അദ്ദേഹം പറഞ്ഞു: തന്റെ ഉമ്മത്തിനെ വിഷമത്തിലാക്കാതിരിക്കാൻ അവിടുന്ന് ഉദ്ദേശിച്ചു. മറ്റൊരു നിവേദനം: മദീനായിൽ വെച്ച് എട്ടും ഏഴുമായി (റക്അത്) റസൂൽ(സ) ഞങ്ങൾക്ക് (ഇമാമായി) ളുഹറും, അസ്റും ചേർത്തും, മഗ്രിബും ഇശാഉം ചേർത്തും നിസ്കരിച്ചു. മറ്റൊരു നിവേദനം: മഴയില്ലാത്ത അവസ്ഥയിൽ എന്നുകൂടിയുണ്ട്. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബിനു അബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=48), 1, 'وَفِي رِوَايَةٍ: جَمَعَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَالْمَغْرِبِ وَالْعِشَاءِ بِالْمَدِينَةِ، مِنْ غَيْرِ خَوْفٍ وَلَا مَطَرٍ. فَقِيلَ لِابْنِ عَبَّاسٍ: مَا أَرَادَ إلَى ذَلِكَ؟ قَالَ: أَرَادَ أَنْ لَا يُحْرِجَ أُمَّتَهُ.', 'മറ്റൊരു നിവേദനപ്രകാരം: മഴയോ, (ശത്രു) ഭയമോ കൂടാതെ മദീനായിൽവെച്ച് ളുഹറും അസറും മഗ്രിബും ഇശാഉം റസൂൽ(സ) ഒരുമിച്ച് നിസ്കരിച്ചു. ഇബ്നുഅബ്ബാസി(റ)നോട് ചോദിക്കപ്പെട്ടു. അതിനാൽ തിരുമേനി(സ) ഉദ്ദേശിച്ചതെന്താണ്. അദ്ദേഹം പറഞ്ഞു: തന്റെ ഉമ്മത്തിനെ വിഷമത്തിലാക്കാതിരിക്കാൻ അവിടുന്ന് ഉദ്ദേശിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=48), 2, 'وَفِي رِوَايَةٍ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ ثَمَانِيًا وَسَبْعًا: الظُّهْرَ وَالْعَصْرَ، وَالْمَغْرِبَ وَالْعِشَاءَ.', 'മറ്റൊരു നിവേദനം: മദീനായിൽ വെച്ച് എട്ടും ഏഴുമായി (റക്അത്) റസൂൽ(സ) ഞങ്ങൾക്ക് (ഇമാമായി) ളുഹറും, അസ്റും ചേർത്തും, മഗ്രിബും ഇശാഉം ചേർത്തും നിസ്കരിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=48), 3, 'وَفِي رِوَايَةٍ: فِي غَيْرِ مَطَرٍ. (ق,د,ت,ن)', 'മറ്റൊരു നിവേദനം: മഴയില്ലാത്ത അവസ്ഥയിൽ എന്നുകൂടിയുണ്ട്. (ബു,മു,ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُسَبِّحُ عَلَى الرَّاحِلَةِ أَيَّ وَجْهٍ تَوَجَّهَ، وَيُوتِرُ عَلَيْهَا، غَيْرَ أَنَّهُ لَا يُصَلِّي الْمَكْتُوبَةَ عَلَيْهَا. (ق,د,ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) യാത്ര ചെയ്യുന്ന വാഹനം ഏത് ഭാഗത്തേക്ക് തിരിയുന്നുവോ ആ ഭാഗത്തേക്ക് (തിരിഞ്ഞ്) സുന്നത്ത് നിസ്കരിക്കുമായിരുന്നു. അതിന്മേൽ അവിടുന്ന് വിത്റും നിസ്കരിക്കുമായിരുന്നു. എന്നാൽ വാഹനത്തിൻ മേൽ അവിടുന്ന് ഫർള് നിസ്കരിക്കുമായിരുന്നില്ല. (ബു,മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إذَا سَافَرَ، فَأَرَادَ أَنْ يَتَطَوَّعَ اسْتَقْبَلَ بِنَاقَتِهِ الْقِبْلَةَ فَكَبَّرَ، ثُمَّ صَلَّى حَيْثُ وَجَّهَهُ رِكَابُهُ. (د)', 'അനസിബ്നുമാലിക്(റ): റസൂൽ(സ) യാത്രയിലായിരിക്കുമ്പോൾ സുന്നത്ത് നിസ്കരിക്കാൻ ഉദ്ദേശിച്ചാൽ ഒട്ടകത്തെ ഖിബ്ലയുടെ ഭാഗത്തേക്ക് തിരിക്കുകയും തക്ബീർ ചൊല്ലുകയും ചെയ്യും. പിന്നീട് വാഹനം അവിടുത്തെ എങ്ങോട്ട് തിരിക്കുന്നുവോ (വാഹനം തിരിയുന്ന ഭാഗത്തേക്ക്) അങ്ങോട്ട് നിസ്കരിക്കുകയും ചെയ്യും. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസിബ്നുമാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى حِمَارٍ، وَهُوَ مُتَوَجِّهٌ إلَى خَيْبَرَ. (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): വൈബറിലേക്ക് അഭിമുഖീകരിച്ചിരിക്കുന്ന കഴുതപ്പുറത്ത് റസൂൽ(സ) നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. (മു,ദ,ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ - يُحَدِّثُ حَدِيثَهُ حِينَ تَخَلَّفَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ - قَالَ: وَصَبَّحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَادِمًا، وَكَانَ إذَا قَدِمَ مِنْ سَفَرٍ بَدَأَ بِالْمَسْجِدِ فَرَكَعَ فِيهِ رَكْعَتَيْنِ، ثُمَّ جَلَسَ لِلنَّاسِ، فَلَمَّا فَعَلَ ذَلِكَ جَاءَهُ الْمُخَلَّفُونَ فَطَفِقُوا يَعْتَذِرُونَ إلَيْهِ وَيَحْلِفُونَ لَهُ، وَكَانُوا بِضْعًا وَثَمَانِينَ رَجُلًا، فَقَبِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَانِيَتَهُمْ وَبَايَعَهُمْ وَاسْتَغْفَرَ لَهُمْ، وَوَكَلَ سَرَائِرَهُمْ إلَى اللهِ عَزَّ وَجَلَّ، حَتَّى جِئْتُ، فَلَمَّا سَلَّمْتُ تَبَسَّمَ تَبَسُّمَ الْمُغْضَبِ، ثُمَّ قَالَ: "تَعَالَ". فَجِئْتُ حَتَّى جَلَسْتُ بَيْنَ يَدَيْهِ، فَقَالَ لِي: "مَا خَلَّفَكَ؟ أَلَمْ تَكُنِ ابْتَعْتَ ظَهْرَكَ". فَقُلْتُ: يَا رَسُولَ اللهِ، إنِّي وَاللهِ لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأَيْتُ أَنِّي سَأَخْرُجُ مِنْ سَخَطِهِ، وَلَقَدْ أُعْطِيتُ جَدَلًا، وَلَكِنْ - وَاللهِ - لَقَدْ عَلِمْتُ لَئِنْ حَدَّثْتُكَ الْيَوْمَ حَدِيثَ كَذِبٍ لِتَرْضَى بِهِ عَنِّي، لَيُوشِكَ أَنَّ اللهَ عَزَّ وَجَلَّ يُسْخِطُكَ عَلَيَّ، وَلَئِنْ حَدَّثْتُكَ حَدِيثَ صِدْقٍ تَجِدُ عَلَيَّ فِيهِ إنِّي لَأَرْجُو فِيهِ عَفْوَ اللهِ، وَاللهِ مَا كُنْتُ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا هَذَا فَقَدْ صَدَقَ. فَقُمْ حَتَّى يَقْضِيَ اللهُ فِيكَ". فَقُمْتُ فَمَضَيْتُ. (ن)', 'കഅ്ബ്നുമാലിക്(റ): - അദ്ദേഹം തബൂക്ക് യുദ്ധത്തിൽ നിന്നും പിന്തിനിന്നതിനെക്കുറിച്ച് വിവരിക്കുന്നു - നബി(സ) (യുദ്ധത്തിൽ നിന്നു) തിരിച്ചെത്തി. യാത്രയിൽനിന്ന് തിരിച്ചെത്തിയാൽ അവിടുന്ന് പള്ളിയിൽ വന്ന് രണ്ട് റക്അത്ത് നിസ്കരിച്ച് ജനങ്ങളുടെ പ്രശ്നങ്ങൾ ആരായുവാൻ കുറച്ചു സമയം വിനിയോഗിക്കുക പതിവായിരുന്നു. ഈ പ്രാവശ്യം പതിവ് കർമ്മങ്ങൾക്കുശേഷം അവിടുന്ന് പള്ളിയിൽ വിശ്രമിച്ചപ്പോൾ യുദ്ധത്തിന് പോകാതിരുന്നയാളുകൾ വന്നു സത്യം ചെയ്തു കാരണങ്ങൾ ബോധിപ്പിച്ചു തുടങ്ങി. അവർ എൺപതിൽപരം പേരുണ്ടായിരുന്നു. അവരുടെ ബാഹ്യമായ ന്യായീരകണങ്ങൾ അവിടുന്ന് സ്വീകരിച്ചു. ചില പ്രതിജ്ഞകൾക്കുശേഷം പാപമോചനത്തിനുവേണ്ടി അവിടുന്ന് പ്രാർത്ഥിക്കുകയും രഹസ്യങ്ങൾ അല്ലാഹുവിലേക്ക് വിടുകയും ചെയ്തു. (രഹസ്യങ്ങളന്വേഷിച്ചു തീർപ്പു കൽപിക്കൽ നബി(സ)യുടെ ചുമതലയിൽപെട്ടതല്ല) അവസാനം ഞാൻ തിരുസന്നിധിയിൽ ചെന്ന് സലാം ചൊല്ലിയപ്പോൾ അൽപം കോപം കലർന്നമട്ടിൽ ഒന്നു പുഞ്ചിരിച്ചുകൊണ്ട് ഇപ്രകാരം പറഞ്ഞു: "ഇവിടെ വരൂ!" ഉടനെ ഞാൻ അവിടുത്തെ മുമ്പിൽ ചെന്നിരുന്നപ്പോൾ "എന്തുകൊണ്ട് നീ തബൂക്കിൽ പങ്കെടുത്തില്ല? അതിനുവേണ്ടി നീ വാഹനം വാങ്ങിയിരുന്നല്ലോ" എന്ന് അവിടുന്ന് ആരാഞ്ഞു. കഅ്ബ്(റ) പറയുകയാണ്: ഞാൻ പറഞ്ഞു: അല്ലാഹുവാണെ! ഞാൻ ഇപ്പോൾ മറ്റേതെങ്കിലും പ്രധാനികളുടെ അടുത്തായിരുന്നെങ്കിൽ അദ്ദേഹത്തിന്റെ കോപത്തിൽനിന്നു രക്ഷപ്പെടാനുള്ള ന്യായീകരണം എനിക്കറിയാം; അതിനുമാത്രം സംസാരവൈഭവമുണ്ടെനിക്ക്. അല്ലാഹുവാണെ! ഇന്ന് അങ്ങയുടെ പ്രീതി സമ്പാദിക്കാൻ ഞാൻ വല്ല അടവും സ്വീകരിച്ചാൽ നാളെ അല്ലാഹു അങ്ങയെ എന്റെ മേൽ കോപിഷ്ടനാക്കും. എന്നാൽ ഞാൻ അങ്ങയോട് സത്യം തുറന്നു പറയുകയാണെങ്കിൽ അവിടുന്ന് എന്നോട് കോപിച്ചേക്കാം, പക്ഷേ അതുകാരണം അല്ലാഹു എനിക്ക് മാപ്പ് നൽകുമെന്ന് ഞാൻ പ്രതീക്ഷിക്കുന്നു. അല്ലാഹുവാണെ! ഞാൻ യുദ്ധത്തിൽ പങ്കെടുക്കുന്നതിൽ നിന്ന് പിന്തിനിന്ന അന്നത്തെപ്പോലെ സാമ്പത്തികശേഷിയും ആരോഗ്യവും മുമ്പൊരിക്കലും എനിക്കുണ്ടായിട്ടുമില്ല. അന്നേരം നബി(സ) ഇങ്ങനെ പറയുകയുണ്ടായി: "ഇയാൾ സത്യം പറഞ്ഞിരിക്കുന്നു. ഇപ്പോൾ നീ സ്ഥലം വിട്ടുകൊള്ളുക. നിന്റെ കാര്യം അല്ലാഹു തീരുമാനിക്കട്ടെ." ഉടനെ ഞാൻ സ്ഥലം വിട്ടുപോയി. (ന)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബ്നുമാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 710, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ، قَالَ: فَجِئْتُ وَهُوَ يُصَلِّي عَلَى رَاحِلَتِهِ نَحْوَ الْمَشْرِقِ، وَالسُّجُودُ أَخْفَضُ مِنَ الرُّكُوعِ. (ق,د,ت,ن,جه)', 'ജാബിർ(റ): എന്നെ റസൂൽ(സ) ഒരാവശ്യത്തിനയച്ചു. ഞാൻ വന്നപ്പോൾ അവിടുന്ന് തന്റെ വാഹനപ്പുറത്ത് കിഴക്കുഭാഗത്തേക്ക് തിരിഞ്ഞു നിസ്കരിക്കുകയായിരുന്നു. അവിടുത്തെ സജൂദ് റുകൂഇനേക്കാൾ ചുരുങ്ങിയതായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى السُّبْحَةَ بِاللَّيْلِ فِي السَّفَرِ، عَلَى ظَهْرِ رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ. (خ)', 'ആമിറുബിനു റബീഅ(റ): യാത്രാവേളയിൽ തിരുമേനി(സ)യുടെ വാഹനത്തിന് മുകളിൽ വാഹനം ഏത് ഭാഗത്തേക്ക് തിരിഞ്ഞാലും ആ അവസ്ഥയിൽ രാത്രി സമയത്തെ സുന്നത്ത് നിസ്കരിക്കുന്നതായി നബി(സ)യെ അദ്ദേഹം കണ്ടു. (ബു)', 'عَامِرِ بْنِ رَبِيعَةَ', 'ആമിറുബിനു റബീഅ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 711, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي التَّطَوُّعَ وَهُوَ رَاكِبٌ فِي غَيْرِ الْقِبْلَةِ. (خ)', 'ജാബിർ ബിൻ അബ്ദുല്ലാ(റ): വാഹനത്തിൽ ഖിബ്ലയുടെ ഭാഗത്തേക്ക് അല്ലാത്ത നിലയിൽ നബി(സ) സുന്നത്ത് (നഫൽ) നിസ്കരിക്കാറുണ്ടായിരുന്നു. (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിർ ബിൻ അബ്ദുല്ലാ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى عَلَى حِمَارٍ وَوَجْهُهُ عَنْ يَسَارِ الْقِبْلَةِ، فَقِيلَ لَهُ: تُصَلِّي لِغَيْرِ الْقِبْلَةِ؟ فَقَالَ: لَوْلَا أَنِّي رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَعَلَهُ لَمْ أَفْعَلْهُ. (خ)', 'അനസ്(റ): തന്റെ മുഖം ഖിബ്ലയുടെ ഇടത് ഭാഗത്തേക്ക് ആയി അദ്ദേഹം കഴുതപ്പുറത്ത് നിസ്കരിച്ചു. അപ്പോൾ അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: ഖിബ്ലയിലേക്ക് അല്ലാതെ താങ്കൾ നിസ്കരിക്കുന്നുവല്ലോ? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇങ്ങനെ ചെയ്തതായി ഞാൻ കണ്ടില്ലായിരുന്നുവെങ്കിൽ ഞാൻ ഇത് ചെയ്യുകയില്ലായിരുന്നു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَصَلَّى بِنَا الْعِشَاءَ الْآخِرَةَ، فَقَرَأَ فِي إحْدَى الرَّكْعَتَيْنِ بِ{التِّينِ وَالزَّيْتُونِ}. (ق,د,ت,ن,جه)', 'ബറാഅ്(റ): റസൂലി(സ)നോടൊപ്പം ഒരു യാത്രയിൽ ഞങ്ങൾ പുറപ്പെട്ടു. തിരുമേനി(സ) ഞങ്ങൾക്ക് ഇമാമായി ഇശാഅ് നിസ്കരിച്ചപ്പോൾ രണ്ടിൽ ഒരു റക്അത്തിൽ ''വത്തീനി വസ്സൈത്തൂൻ....'' എന്ന് തുടങ്ങുന്ന സൂറത്ത് ഓതി. (ബു,മു,ദ,തു,ന,ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا لَمْ تَرَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلَاةَ اللَّيْلِ قَاعِدًا قَطُّ حَتَّى أَسَنَّ، فَكَانَ يَقْرَأُ قَاعِدًا، حَتَّى إذَا أَرَادَ أَنْ يَرْكَعَ قَامَ، فَقَرَأَ نَحْوًا مِنْ ثَلَاثِينَ آيَةً أَوْ أَرْبَعِينَ آيَةً، ثُمَّ رَكَعَ. وَفِي رِوَايَةٍ: ثُمَّ يَفْعَلُ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ، فَإذَا قَضَى صَلَاتَهُ نَظَرَ: فَإنْ كُنْتُ يَقْظَى تَحَدَّثَ مَعِي، وَإنْ كُنْتُ نَائِمَةً اضْطَجَعَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ഉമ്മുൽ മുഅ്മിനീൻ ആയിശ(റ): റസൂലി(സ)ന് പ്രായാധിക്യം ഉണ്ടാകുന്നത് വരെ രാത്രി നിസ്കാരം തിരുമേനി(സ) ഇരുന്ന് നിസ്കരിച്ചതായി മഹതി കണ്ടിട്ടില്ല. (പ്രായാധിക്യം ഉണ്ടായപ്പോൾ) തിരുമേനി(സ) ഇരുന്ന് ഓതുകയും റുകൂഅ് ചെയ്യുവാൻ വിചാരിച്ചാൽ തിരുമേനി(സ) എഴുന്നേൽക്കുകയും ചെയ്യുമായിരുന്നു. മുപ്പതോ നാൽപതോ ആയത്ത് ഓതുകയും പിന്നീട് അവിടുന്ന് റുകൂഅ് ചെയ്യുകയും ചെയ്യുമായിരുന്നു. ആയിശ(റ)യിൽ നിന്നും മറ്റൊരു നിവേദനത്തിൽ: പിന്നീട് രണ്ടാമത്തെ റക്അത്തിലും തിരുമേനി(സ) അതേ പ്രകാരം ചെയ്യുമായിരുന്നു. നിസ്കാരം കഴിഞ്ഞാൽ അവിടുന്ന് എന്നെ വീക്ഷിക്കും, ഞാൻ ഉണർന്ന് കിടന്നിരുന്നാൽ അവിടുന്ന് എന്നോട് സംസാരിക്കും, ഞാൻ ഉറക്കത്തിലായിരുന്നാൽ തിരുമേനി(സ)യും ചെരിഞ്ഞ് കിടക്കും. (ബു)', 'عَائِشَةَ أُمِّ الْمُؤْمِنِينَ', 'ഉമ്മുൽ മുഅ്മിനീൻ ആയിശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=58), 1, 'وَفِي رِوَايَةٍ: ثُمَّ يَفْعَلُ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ، فَإذَا قَضَى صَلَاتَهُ نَظَرَ: فَإنْ كُنْتُ يَقْظَى تَحَدَّثَ مَعِي، وَإنْ كُنْتُ نَائِمَةً اضْطَجَعَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ: പിന്നീട് രണ്ടാമത്തെ റക്അത്തിലും തിരുമേനി(സ) അതേ പ്രകാരം ചെയ്യുമായിരുന്നു. നിസ്കാരം കഴിഞ്ഞാൽ അവിടുന്ന് എന്നെ വീക്ഷിക്കും, ഞാൻ ഉണർന്ന് കിടന്നിരുന്നാൽ അവിടുന്ന് എന്നോട് സംസാരിക്കും, ഞാൻ ഉറക്കത്തിലായിരുന്നാൽ തിരുമേനി(സ)യും ചെരിഞ്ഞ് കിടക്കും. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ صَلَاةِ الظُّهْرِ وَالْعَصْرِ إذَا كَانَ عَلَى ظَهْرِ سَيْرٍ، وَيَجْمَعُ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) യാത്രയിലായിരുന്നാൽ ളുഹ്റും അസ്റും ഒരുമിച്ച് നിസ്കരിക്കുമായിരുന്നു. മഗ്രിബും ഇശാഉം ഇപ്രകാരം അവിടുന്ന് ഒരുമിച്ച് തന്നെയായിരുന്നു നിസ്കരിച്ചിരുന്നത്. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 712, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنَ الْمَدِينَةِ إلَى مَكَّةَ، فَصَلَّى رَكْعَتَيْنِ رَكْعَتَيْنِ حَتَّى رَجَعَ. قُلْتُ: كَمْ أَقَامَ بِمَكَّةَ؟ قَالَ: عَشْرًا. وَفِي رِوَايَةٍ: خَرَجْنَا مِنَ الْمَدِينَةِ إلَى الْحَجِّ. (ق,د,ت,ن,جه)', 'അനസ്(റ): റസൂൽ(സ)യോടൊപ്പം മദീനായിൽ നിന്നും ഞങ്ങൾ മക്കയിലേക്ക് പുറപ്പെട്ടു. തിരുമേനി(സ) മടങ്ങുന്നത് വരെ രണ്ട് രണ്ട് റക്അത്തായി നിസ്കരിച്ചു. ഞാൻ ചോദിച്ചു. തിരുമേനി(സ) മക്കയിൽ എത്ര ദിവസം താമസിച്ചു? അദ്ദേഹം പറഞ്ഞു: പത്തു ദിവസം. മറ്റൊരു റിപ്പോർട്ടിൽ: മദീനയിൽ നിന്നും ഹജ്ജിനായി ഞങ്ങൾ പുറപ്പെട്ടു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=29 and h.hadith_no=60), 1, 'وَفِي رِوَايَةٍ: خَرَجْنَا مِنَ الْمَدِينَةِ إلَى الْحَجِّ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: മദീനയിൽ നിന്നും ഹജ്ജിനായി ഞങ്ങൾ പുറപ്പെട്ടു. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِتَبُوكَ عِشْرِينَ يَوْمًا يَقْصُرُ الصَّلَاةَ. (د)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നിസ്കാരത്തെ ചുരുക്കുന്ന നിലയിൽ ഇരുപത് ദിവസം റസൂൽ(സ) തബൂകിൽ താമസിച്ചു. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ مُوسَى بْنِ سَلَمَةَ: أَنَّهُ سَأَلَ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قُلْتُ: تَفُوتُنِي الصَّلَاةُ فِي جَمَاعَةٍ وَأَنَا بِالْبَطْحَاءِ، مَا تَرَى أَنْ أُصَلِّيَ؟ قَالَ: رَكْعَتَيْنِ، سُنَّةَ أَبِي الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'മൂസബ്നു സലമ(റ): അദ്ദേഹം ഇബ്നുഅബ്ബാസി(റ)നോട് ചോദിച്ചു: ഞാൻ ബത്ഹാഇൽ ആയിരുന്നപ്പോൾ എനിക്ക് ജമാഅത്ത് നിസ്കാരം നഷ്ടപ്പെടുന്നു; ഞാൻ എങ്ങനെ നിസ്കരിക്കണമെന്നാണ് താങ്കൾ കാണുന്നത്? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: രണ്ട് റക്അത്ത്, അതാണ് അബുൽ ഖാസിം(സ)യുടെ മാതൃക. (ന)', 'مُوسَى بْنِ سَلَمَةَ', 'മൂസബ്നു സലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ بِي بَوَاسِيرُ، فَسَأَلْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلَاةِ، فَقَالَ: "صَلِّ قَائِمًا، فَإنْ لَمْ تَسْتَطِعْ فَقَاعِدًا، فَإنْ لَمْ تَسْتَطِعْ فَعَلَى جَنْبٍ". (خ)', 'ഇംറാൻ ബിൻ ഹുസൈൻ(റ): എനിക്ക് അർശസുണ്ടായിരുന്നു. അതിനാൽ നിസ്കാരത്തെപ്പറ്റി നബിയോട് ഞാൻ ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "നീ നിന്ന് നിസ്കരിക്കുക നിനക്ക് കഴിയാത്തപ്പോൾ നീ ഇരുന്ന് നിസ്കരിക്കുക. അതിനും കഴിയാത്തപ്പോൾ നീ ഒരു ഭാഗത്തേക്ക് ചെരിഞ്ഞ് കിടന്ന് നിസ്കരിക്കുക." (ബു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാൻ ബിൻ ഹുസൈൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَعْجَبُ رَبُّكُمْ مِنْ رَاعِي غَنَمٍ فِي رَأْسِ شَظِيَّةٍ بِجَبَلٍ، يُؤَذِّنُ بِالصَّلَاةِ وَيُصَلِّي، فَيَقُولُ اللهُ عَزَّ وَجَلَّ: انْظُرُوا إلَى عَبْدِي هَذَا: يُؤَذِّنُ وَيُقِيمُ الصَّلَاةَ، يَخَافُ مِنِّي، قَدْ غَفَرْتُ لِعَبْدِي، وَأَدْخَلْتُهُ الْجَنَّةَ". (د,ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "മലയുടെ ഉപരിഭാഗത്ത് (ഉച്ചിയിൽ) ആട് മേക്കുന്ന ഒരുവനെപ്പറ്റി നിങ്ങളുടെ റബ്ബ് അത്ഭുതം കൂറുന്നു. അയാൾ ബാങ്ക് വിളിക്കുകയും നിസ്കരിക്കുകയും ചെയ്യുന്നു. അപ്പോൾ അല്ലാഹു ഇപ്രകാരം പറയും: നിങ്ങൾ എന്റെ ഈ ദാസനെ നോക്കൂ. അയാൾ ബാങ്ക് വിളിക്കുകയും നിസ്കാരത്തെ നിലനിർത്തുകയും ചെയ്യുന്നു. അയാൾ എന്നെ ഭയപ്പെടുന്നു. നിശ്ചയം, എന്റെ ദാസന് ഞാൻ പൊറുത്ത് കൊടുത്തു. അവനെ ഞാൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയും ചെയ്തു." (ദ,ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إذَا كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي السَّفَرِ فَقُلْنَا: زَالَتِ الشَّمْسُ؟ أَوْ: لَمْ تَزُلْ؟ صَلَّى الظُّهْرَ ثُمَّ ارْتَحَلَ. (د)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യോടൊപ്പം യാത്രയിലായാൽ ഞങ്ങൾ പറയും: സൂര്യൻ (ആകാശമധ്യത്തിൽനിന്നും) തെറ്റിയോ? അതല്ല തെറ്റിയില്ലേ? (അപ്പോൾ) നബി(സ) ദുഹ്ർ നിസ്കരിക്കുകയും പിന്നെ യാത്ര തുടരുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا نَزَلَ مَنْزِلًا لَمْ يَرْتَحِلْ حَتَّى يُصَلِّيَ الظُّهْرَ. فَقَالَ لَهُ رَجُلٌ: وَإنْ كَانَ بِنِصْفِ النَّهَارِ؟ قَالَ: وَإنْ كَانَ بِنِصْفِ النَّهَارِ. (د,ن)', 'അനബ്നു മാലിക്(റ): നബി(സ) യാത്രക്കിടയിൽ ഒരു സ്ഥലത്തിറങ്ങിയാൽ ളുഹ്ർ നിസ്കരിക്കാതെ യാത്ര പുനരാരംഭിക്കാറില്ല. അപ്പോൾ ഒരാൾ അനസി(റ)നോട് ചോദിച്ചു: നട്ടുച്ചയ്ക്കാണെങ്കിലൊ? അദ്ദേഹം പറഞ്ഞു: അതെ നട്ടുച്ചക്കായിരുന്നാലും. (ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനബ്നു മാലിക്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، فَأَبْطَأَ بِي جَمَلِي وَأَعْيَى، ثُمَّ قَدِمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبْلِي وَقَدِمْتُ بِالْغَدَاةِ، فَجِئْتُ الْمَسْجِدَ، فَوَجَدْتُهُ عَلَى بَابِ الْمَسْجِدِ، قَالَ: "الْآنَ حِينَ قَدِمْتَ". قُلْتُ: نَعَمْ. قَالَ: "فَدَعْ جَمَلَكَ، وَادْخُلْ فَصَلِّ رَكْعَتَيْنِ". قَالَ: فَدَخَلْتُ فَصَلَّيْتُ ثُمَّ رَجَعْتُ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂലി(സ)നോടൊപ്പം ഒരു യുദ്ധത്തിന് ഞാൻ പുറപ്പെട്ടു. എന്റെ ഒട്ടകം എന്നെ പിന്തിച്ചു. അത് ക്ഷീണിക്കുകയും ചെയ്തു. റസൂൽ(സ) എന്നെക്കാൾ മുമ്പ് മടങ്ങിയെത്തി. ഞാൻ അതിരാവിലെ മടങ്ങിയെത്തി. ഞാൻ പള്ളിയിൽ വന്നു. പള്ളിയുടെ വാതിലിൽ അവിടുത്തെ ഞാൻ കണ്ടു. അവിടുന്ന് ചോദിച്ചു: "ഇപ്പോഴാണോ നീ എത്തിയത്?" ഞാൻ പറഞ്ഞു: അതെ, റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഒട്ടകത്തെ വിട്ടേക്കുക, എന്നിട്ട് പള്ളിയിൽ പ്രവേശിച്ച് രണ്ട് റക്അത്ത് നിസ്കരിക്കുക." ജാബിർ(റ) പറയുന്നു: ഞാൻ പള്ളിയിൽ പ്രവേശിക്കുകയും രണ്ട് റക്അത്ത് നിസ്കരിക്കുകയും ശേഷം മടങ്ങുകയും ചെയ്തു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=29 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
